  {
    "lvgl_app_start",
    NULL
  };

  (void)task_create("lvgl_app_start",
                    CONFIG_LVGL_APP_APP_MAIN_PRIORITY,
                    2048,
                    lvgl_app_autostart_entry,
                    argv);
}
