  if (g_lvgl_result.indev != NULL)
    {
      lv_indev_set_display(g_lvgl_result.indev, disp);
    }
#endif

  return 0;
}

static int lvgl_app_try_display_init(const char *fb_path,
                                     const char *input_path)
{
