    {
      syslog(LOG_WARNING, "%s: framebuffer requires RGB565 compat: %s\n",
             LVGL_APP_TAG, fb_path);
      return lvgl_app_try_fbdev_compat_init(fb_path, input_path);
    }

  return lvgl_app_try_nuttx_init(fb_path, input_path);
}

