static const char *TAG = "rvt_ai_tool";
static rvt_event_bus_t *g_tool_bus;
static int g_tool_handle = -1;

static void ai_chat_tool_publish_result(const rvt_ai_tool_request_t *request,
                                        bool success,
                                        int error_code,
                                        const char *content)
{
    rvt_ai_tool_result_t result;

    if (!g_tool_bus || !request)
        return;

    memset(&result, 0, sizeof(result));
    snprintf(result.call_id, sizeof(result.call_id), "%s", request->call_id);
    result.success = success;
    result.error_code = error_code;
    snprintf(result.content, sizeof(result.content), "%s", content ? content : "");
    rvt_event_bus_publish(g_tool_bus, RVT_AI_EVENT_TOOL_RESULT, &result);
}

static int ai_chat_tool_set_volume(int level)
{
    if (level < 0)
        level = 0;
    if (level > 100)
        level = 100;

#if defined(RIVOTEK_AI_TOOL_USE_CODEC_VOLUME)
    if (register_codec) {
        codec_set_volume(register_codec, (uint8_t)level);
        return 0;
    }
#endif

    /*
     * The current audio_service has transport controls but no volume API. Keep
     * the command acknowledged here and enable RIVOTEK_AI_TOOL_USE_CODEC_VOLUME
     * on boards that expose a registered codec volume control.
     */
    RVT_LOGI(TAG, "volume command placeholder level=%d", level);
    return 0;
}

static int ai_chat_tool_set_time(int hour, int minute)
{
    struct timeval tv;
    struct tm now_tm;
    time_t now;

    if (hour < 0 || hour > 23 || minute < 0 || minute > 59)
        return -1;

    now = time(NULL);
    if (localtime_r(&now, &now_tm) == NULL)
        memset(&now_tm, 0, sizeof(now_tm));

    now_tm.tm_hour = hour;
    now_tm.tm_min = minute;
    now_tm.tm_sec = 0;
    tv.tv_sec = mktime(&now_tm);
    tv.tv_usec = 0;

    return settimeofday(&tv, NULL);
}

static void ai_chat_tool_handle_weather(const rvt_ai_tool_request_t *request)
{
    char result[RVT_AI_TEXT_MAX_LEN];

    snprintf(result,
             sizeof(result),
             "%s天气：%s，温度%s，%s",
             request->arg[0] ? request->arg : "当前城市",
             rvt_weather_service_get_desc_text(),
             rvt_weather_service_get_temp_text(),
             rvt_weather_service_get_air_quality_text());
    ai_chat_tool_publish_result(request, true, 0, result);
}

static void ai_chat_tool_handle_request(const rvt_ai_tool_request_t *request)
{
    char text[RVT_AI_TEXT_MAX_LEN];
    int ret = 0;

    if (!request)
        return;

    switch (request->type) {
    case RVT_AI_TOOL_SET_VOLUME:
        ret = ai_chat_tool_set_volume(request->int_value);
        snprintf(text, sizeof(text), "音量已设置为%d%%", request->int_value);
        ai_chat_tool_publish_result(request, ret == 0, ret, text);
        break;
    case RVT_AI_TOOL_GET_WEATHER:
        ai_chat_tool_handle_weather(request);
        break;
    case RVT_AI_TOOL_SET_TIME:
        ret = ai_chat_tool_set_time(request->hour, request->minute);
        snprintf(text, sizeof(text), "时间已设置为%02d:%02d", request->hour, request->minute);
        ai_chat_tool_publish_result(request, ret == 0, ret, text);
        break;
    case RVT_AI_TOOL_PLAY_AUDIO:
        ret = rvt_audio_toggle_play_pause();
        snprintf(text,
                 sizeof(text),
                 "已发送播放请求：%s",
                 request->arg[0] ? request->arg : "默认音频");
        ai_chat_tool_publish_result(request, ret >= 0, ret, text);
        break;
    default:
        ai_chat_tool_publish_result(request, false, -1, "未知工具调用");
        break;
    }
}

static void ai_chat_tool_event_cb(void *user_data, const rvt_event_t *event)
{
    (void)user_data;

    if (!event || event->id != RVT_AI_EVENT_TOOL_REQUEST || !event->data)
        return;

    ai_chat_tool_handle_request((const rvt_ai_tool_request_t *)event->data);
}

int ai_chat_tool_bridge_init(rvt_event_bus_t *event_bus)
{
    if (!event_bus)
        return -1;

    g_tool_bus = event_bus;
    if (g_tool_handle < 0) {
        g_tool_handle = rvt_event_bus_subscribe(event_bus,
                                                RVT_AI_EVENT_TOOL_REQUEST,
                                                ai_chat_tool_event_cb,
                                                NULL);
    }

    return g_tool_handle < 0 ? -1 : 0;
}

