static uint16_t scooter_interpolate_speed(uint16_t start_speed,
                                          uint16_t end_speed,
                                          uint32_t elapsed_ms,
                                          uint32_t duration_ms)
{
    int32_t delta;

    if (duration_ms == 0U || elapsed_ms >= duration_ms)
        return end_speed;

    delta = (int32_t)end_speed - (int32_t)start_speed;
    return (uint16_t)((int32_t)start_speed +
                      (delta * (int32_t)elapsed_ms) / (int32_t)duration_ms);
}

static void scooter_board_service_apply_demo_state(scooter_state_t *state,
                                                   uint16_t speed_kmh,
                                                   char gear,
                                                   scooter_driver_demo_effect_t effect,
                                                   bool running)
{
    if (!state)
        return;

    state->speed_kmh = speed_kmh;
    state->drive_mode = SCOOTER_DRIVE_MODE_DRIVE;
    state->gear[0] = gear;
    state->gear[1] = '\0';
    state->driver_demo_effect = effect;
    state->driver_demo_running = running;
    state->battery_percent = 100U;
    state->range_km = 121U;
    state->trip_meters = 999900U;
    state->controller_online = true;
}

