    case RVT_AI_VOICE_UI_SKILL_REPLY:
        ai_chat_disarm_idle_timer(view);
        ai_chat_set_status(view, "正在回复", true);
        if (!ai_chat_text_is_only_punctuation(voice_event->text))
            ai_chat_set_dialog(view, voice_event->text);
        break;
    case RVT_AI_VOICE_UI_VEHICLE_SELFCHECK:
        ai_chat_disarm_idle_timer(view);
        ai_chat_cancel_flow_timers(view);
        view->pending_action = AI_CHAT_PENDING_SELFCHECK_START;
        if (!ai_chat_view_is_visible(view))
            ai_chat_view_show(view);
        ai_chat_set_status(view, "正在回复", true);
        ai_chat_set_dialog(view, voice_event->text[0] ? voice_event->text : "车辆自检中……");
        ai_chat_start_oneshot_timer(&view->selfcheck_show_timer,
                                    ai_chat_selfcheck_show_timer_cb,
                                    AI_CHAT_SELFCHECK_AUTO_SHOW_MS,
                                    view);
        break;
    case RVT_AI_VOICE_UI_BATTERY_REMINDER:
        ai_chat_disarm_idle_timer(view);
        ai_chat_cancel_flow_timers(view);
        view->pending_action = AI_CHAT_PENDING_BATTERY_CONFIRM;
        if (!ai_chat_view_is_visible(view))
            ai_chat_view_show(view);
        ai_chat_set_status(view, "正在回复", true);
        ai_chat_set_dialog(view,
                           voice_event->text[0] ? voice_event->text :
                           "我记下了，当电量低于 30%时，我会提醒您充电哦！");
        ai_chat_start_oneshot_timer(&view->battery_remind_timer,
                                    ai_chat_battery_remind_timer_cb,
                                    AI_CHAT_BATTERY_AUTO_REMIND_MS,
                                    view);
        break;
    case RVT_AI_VOICE_UI_TTS_DONE:
        if (view->pending_action == AI_CHAT_PENDING_SELFCHECK_START) {
            ai_chat_delete_timer(&view->selfcheck_show_timer);
            ai_chat_start_oneshot_timer(&view->selfcheck_show_timer,
                                        ai_chat_selfcheck_result_timer_cb,
                                        AI_CHAT_SELFCHECK_SHOW_MS,
                                        view);
            break;
        }
        if (view->pending_action == AI_CHAT_PENDING_SELFCHECK_RESULT) {
            ai_chat_set_status(view, "自检完成", false);
            ai_chat_start_oneshot_timer(&view->selfcheck_back_timer,
                                        ai_chat_selfcheck_back_timer_cb,
                                        AI_CHAT_SELFCHECK_BACK_MS,
                                        view);
            break;
        }
        if (view->pending_action == AI_CHAT_PENDING_BATTERY_CONFIRM) {
            ai_chat_start_battery_reminder_flow(view, AI_CHAT_BATTERY_REMIND_MS);
            break;
        }
        if (view->pending_action == AI_CHAT_PENDING_BATTERY_ALERT) {
            ai_chat_finish_battery_alert(view);
            break;
        }
        ai_chat_set_status(view, "我在听", false);
        ai_chat_set_dialog(view, "等待指令。");
        ai_chat_arm_idle_timer(view);
        break;
    case RVT_AI_VOICE_UI_EXIT_REQUESTED:
    case RVT_AI_VOICE_UI_STOPPED:
        ai_chat_disarm_idle_timer(view);
        ai_chat_reset_flow(view);
        view->exit_stop_voice = false;
        view->exit_requested = true;
        ai_chat_view_hide(view);
        break;
    case RVT_AI_VOICE_UI_ERROR:
        ai_chat_disarm_idle_timer(view);
        ai_chat_reset_flow(view);
        ai_chat_set_status(view, "语音助手异常", false);
