void ai_chat_view_poll(ai_chat_view_t *view)
{
    rvt_ai_voice_ui_event_t event;
    rt_base_t level;

    if (!view)
        return;

    for (;;) {
        bool has_event;

        level = rt_hw_interrupt_disable();
        has_event = view->pending_event.tail != view->pending_event.head;
        if (has_event) {
            event = view->pending_event.events[view->pending_event.tail];
            view->pending_event.tail =
                (uint8_t)((view->pending_event.tail + 1U) %
                          AI_CHAT_PENDING_EVENT_CAPACITY);
        }
        rt_hw_interrupt_enable(level);

        if (!has_event)
            return;

        ai_chat_apply_voice_event(view, &event);
    }
}

static void ai_chat_voice_event_cb(void *user_data, const rvt_event_t *event)
{
    ai_chat_view_t *view = user_data;
    rt_base_t level;

    if (!view || !event || event->id != RVT_AI_VOICE_EVENT_UI || !event->data)
        return;

    level = rt_hw_interrupt_disable();
    {
        uint8_t next_head =
            (uint8_t)((view->pending_event.head + 1U) %
                      AI_CHAT_PENDING_EVENT_CAPACITY);
        if (next_head == view->pending_event.tail) {
            view->pending_event.tail =
                (uint8_t)((view->pending_event.tail + 1U) %
                          AI_CHAT_PENDING_EVENT_CAPACITY);
        }
        view->pending_event.events[view->pending_event.head] =
            *(const rvt_ai_voice_ui_event_t *)event->data;
        view->pending_event.head = next_head;
    }
    rt_hw_interrupt_enable(level);
}

static void ai_chat_screen_event_cb(lv_event_t *e)
{
    ai_chat_view_t *view = lv_event_get_user_data(e);

    if (!view || lv_event_get_code(e) != LV_EVENT_DELETE)
        return;

    ai_chat_disarm_idle_timer(view);
    ai_chat_reset_flow(view);
    ai_chat_destroy_fonts(view);
    if (view->event_bus && view->voice_handle >= 0) {
        rvt_event_bus_unsubscribe(view->event_bus, view->voice_handle);
        view->voice_handle = -1;
    }
}

