static void scooter_shell_view_ai_voice_start_entry(void *parameter)
{
    scooter_shell_view_t *view = parameter;
    int ret;

    if (!view)
        return;

    if (!view->ai_voice_start_requested) {
        view->ai_voice_starting = false;
        return;
    }

    ret = ai_voice_start_capture();
    if (ret < 0) {
        SCOOTER_SHELL_LOG("failed to start ai voice");
        view->ai_voice_start_requested = false;
    } else if (!view->ai_session_active || !view->ai_voice_start_requested) {
        (void)ai_voice_stop_capture();
    }

    view->ai_voice_starting = false;
}
#endif

static void scooter_shell_view_enter_ai(scooter_shell_view_t *view)
{
    if (!view)
        return;

    view->ai_restore_page = view->page_manager.active_page;
    view->ai_session_active = true;
    if (view->ai_restore_page == SCOOTER_PAGE_NAVIGATION) {
        scooter_cast_ui_layer_manager_exit_projection(&view->cast_ui_layer_manager);
        scooter_navigation_view_hide(&view->navigation_view);
        scooter_shell_view_request_nav_work(view, SCOOTER_SHELL_NAV_WORK_STOP);
    }
    ai_chat_view_show(&view->ai_chat_view);
    view->ai_input_guard_tick = lv_tick_get();

#if defined(RIVOTEK_APP_SCOOTER_UI_AI_VOICE)
    if (!view->ai_voice_starting) {
#if (SCOOTER_DEMO_HAL_SYSTEM == SCOOTER_DEMO_HAL_SYSTEM_RTTHREAD)
        rt_thread_t thread;

        view->ai_voice_start_requested = true;
        view->ai_voice_starting = true;
        thread = rt_thread_create("ai_start",
                                  scooter_shell_view_ai_voice_start_entry,
                                  view,
                                  SCOOTER_SHELL_AI_START_THREAD_STACK,
                                  SCOOTER_SHELL_AI_START_THREAD_PRIORITY,
                                  20);
        if (thread) {
            rt_thread_startup(thread);
        } else {
            view->ai_voice_starting = false;
            if (ai_voice_start_capture() < 0) {
                view->ai_voice_start_requested = false;
                SCOOTER_SHELL_LOG("failed to start ai voice");
            }
        }
#else
        view->ai_voice_start_requested = true;
        if (ai_voice_start_capture() < 0) {
            view->ai_voice_start_requested = false;
            SCOOTER_SHELL_LOG("failed to start ai voice");
        }
#endif
    }
#endif
}

static void scooter_shell_view_exit_ai(scooter_shell_view_t *view, bool stop_voice)
{
    scooter_page_id_t restore_page;

    if (!view)
        return;

    restore_page = view->ai_restore_page;
    if (restore_page >= SCOOTER_PAGE_COUNT)
        restore_page = view->page_manager.active_page;

    view->ai_session_active = false;
    view->ai_voice_start_requested = false;
    ai_chat_view_hide(&view->ai_chat_view);

#if defined(RIVOTEK_APP_SCOOTER_UI_AI_VOICE)
    if (stop_voice)
        (void)ai_voice_stop_capture();
#else
    (void)stop_voice;
#endif

    if (view->nav_restore_valid &&
        view->page_manager.active_page == SCOOTER_PAGE_NAVIGATION) {
        scooter_shell_view_exit_navigation_page(view);
    } else if (view->nav_restore_valid) {
        scooter_shell_view_switch_page(view, SCOOTER_PAGE_NAVIGATION);
    } else if (restore_page < SCOOTER_PAGE_COUNT) {
        scooter_shell_view_switch_page(view, restore_page);
    }
}

