#define SCOOTER_DRIVER_DEMO_BRAKE_TO_10_MS 3000U
#define SCOOTER_DRIVER_DEMO_HOLD_10_MS     3000U
#define SCOOTER_DRIVER_DEMO_BRAKE_TO_0_MS  3000U
#define SCOOTER_DRIVER_DEMO_EFFECT_MS      5000U

typedef enum {
    SCOOTER_DRIVER_DEMO_IDLE = 0,
    SCOOTER_DRIVER_DEMO_RAMP_TO_10,
    SCOOTER_DRIVER_DEMO_ACCEL_TO_25,
    SCOOTER_DRIVER_DEMO_CRUISE_25,
    SCOOTER_DRIVER_DEMO_BRAKE_TO_10,
    SCOOTER_DRIVER_DEMO_HOLD_10,
    SCOOTER_DRIVER_DEMO_BRAKE_TO_0,
} scooter_driver_demo_phase_t;

static uint16_t scooter_interpolate_speed(uint16_t start_speed,
                                          uint16_t end_speed,
                                          uint32_t elapsed_ms,
                                          uint32_t duration_ms)
{
    int32_t delta;

    if (duration_ms == 0U || elapsed_ms >= duration_ms)
        return end_speed;

    delta = (int32_t)end_speed - (int32_t)start_speed;
    return (uint16_t)((int32_t)start_speed +
                      (delta * (int32_t)elapsed_ms) / (int32_t)duration_ms);
}

static void scooter_board_service_apply_demo_state(scooter_state_t *state,
                                                   uint16_t speed_kmh,
                                                   char gear,
                                                   scooter_driver_demo_effect_t effect,
                                                   bool running)
{
    if (!state)
        return;

    state->speed_kmh = speed_kmh;
    state->drive_mode = SCOOTER_DRIVE_MODE_DRIVE;
    state->gear[0] = gear;
    state->gear[1] = '\0';
    state->driver_demo_effect = effect;
    state->driver_demo_running = running;
    state->battery_percent = 100U;
    state->range_km = 121U;
    state->trip_meters = 999900U;
    state->controller_online = true;
}

static void scooter_board_service_finish_demo(scooter_board_service_t *service)
{
    if (!service)
        return;

    service->demo_running = false;
    service->demo_pending_reset_output = true;
    service->demo_phase = SCOOTER_DRIVER_DEMO_IDLE;
    service->demo_effect_end_tick = 0U;
    service->demo_effect = SCOOTER_DRIVER_DEMO_EFFECT_NONE;
}

static bool scooter_board_service_update_demo(scooter_board_service_t *service,
                                              scooter_state_t *state)
{
    uint32_t now_ms;
    uint32_t elapsed_ms;
    bool phase_changed;

    if (!service || !state)
        return false;

    if (!service->demo_running) {
        if (service->demo_pending_reset_output) {
            service->demo_pending_reset_output = false;
            scooter_board_service_apply_demo_state(state, 0U,
                                                   'P',
                                                   SCOOTER_DRIVER_DEMO_EFFECT_NONE,
                                                   false);
            return true;
        }

        return false;
    }

    now_ms = service->tick_count * SCOOTER_DEMO_REFRESH_PERIOD_MS;
    do {
        phase_changed = false;
        elapsed_ms = now_ms - service->demo_phase_start_tick;

        switch ((scooter_driver_demo_phase_t)service->demo_phase) {
        case SCOOTER_DRIVER_DEMO_RAMP_TO_10:
            if (elapsed_ms >= SCOOTER_DRIVER_DEMO_RAMP_TO_10_MS) {
                service->demo_phase = SCOOTER_DRIVER_DEMO_ACCEL_TO_25;
                service->demo_phase_start_tick += SCOOTER_DRIVER_DEMO_RAMP_TO_10_MS;
                service->demo_effect = SCOOTER_DRIVER_DEMO_EFFECT_ACCEL;
                service->demo_effect_end_tick = now_ms + SCOOTER_DRIVER_DEMO_EFFECT_MS;
                phase_changed = true;
            }
            break;
        case SCOOTER_DRIVER_DEMO_ACCEL_TO_25:
            if (elapsed_ms >= SCOOTER_DRIVER_DEMO_ACCEL_TO_25_MS) {
                service->demo_phase = SCOOTER_DRIVER_DEMO_CRUISE_25;
                service->demo_phase_start_tick += SCOOTER_DRIVER_DEMO_ACCEL_TO_25_MS;
                phase_changed = true;
            }
            break;
        case SCOOTER_DRIVER_DEMO_CRUISE_25:
            if (elapsed_ms >= SCOOTER_DRIVER_DEMO_CRUISE_25_MS) {
                service->demo_phase = SCOOTER_DRIVER_DEMO_BRAKE_TO_10;
                service->demo_phase_start_tick += SCOOTER_DRIVER_DEMO_CRUISE_25_MS;
                service->demo_effect = SCOOTER_DRIVER_DEMO_EFFECT_BRAKE;
                service->demo_effect_end_tick = now_ms + SCOOTER_DRIVER_DEMO_EFFECT_MS;
                phase_changed = true;
            }
            break;
        case SCOOTER_DRIVER_DEMO_BRAKE_TO_10:
            if (elapsed_ms >= SCOOTER_DRIVER_DEMO_BRAKE_TO_10_MS) {
                service->demo_phase = SCOOTER_DRIVER_DEMO_HOLD_10;
                service->demo_phase_start_tick += SCOOTER_DRIVER_DEMO_BRAKE_TO_10_MS;
                phase_changed = true;
            }
            break;
        case SCOOTER_DRIVER_DEMO_HOLD_10:
            if (elapsed_ms >= SCOOTER_DRIVER_DEMO_HOLD_10_MS) {
                service->demo_phase = SCOOTER_DRIVER_DEMO_BRAKE_TO_0;
                service->demo_phase_start_tick += SCOOTER_DRIVER_DEMO_HOLD_10_MS;
                phase_changed = true;
            }
            break;
        case SCOOTER_DRIVER_DEMO_BRAKE_TO_0:
            if (elapsed_ms >= SCOOTER_DRIVER_DEMO_BRAKE_TO_0_MS) {
                scooter_board_service_finish_demo(service);
                phase_changed = true;
            }
            break;
        case SCOOTER_DRIVER_DEMO_IDLE:
        default:
            break;
        }
    } while (phase_changed);

    if (service->demo_effect != SCOOTER_DRIVER_DEMO_EFFECT_NONE &&
        now_ms >= service->demo_effect_end_tick) {
        service->demo_effect = SCOOTER_DRIVER_DEMO_EFFECT_NONE;
    }

    elapsed_ms = now_ms - service->demo_phase_start_tick;
    switch ((scooter_driver_demo_phase_t)service->demo_phase) {
