/* 根据编译配置选择对应的 HAL 操作表。 */
static const rvt_display_ops_t *rvt_display_select_ops(void)
{
#if RVT_USING_RTTHREAD
    return rvt_display_rtthread_get_ops();
#else
    return rvt_display_stub_get_ops();
#endif
}

/* 获取当前 HAL 操作表，必要时延迟初始化。 */
static const rvt_display_ops_t *rvt_display_require_ops(void)
{
    if (!g_rvt_display_ops)
        g_rvt_display_ops = rvt_display_select_ops();

    return g_rvt_display_ops;
}

/* 初始化底层 HAL。 */
int rvt_display_init(void)
{
    const rvt_display_ops_t *ops = rvt_display_require_ops();
    int ret;

    if (!ops)
        return -1;

    ret = 0;
    if (ops->init) {
        ret = ops->init();
        if (ret < 0)
            return ret;
    }

    return ret;
}

