#include <stddef.h>
#include <string.h>

#include "event_bus/event_bus.h"
#include "rivotek/rivotek_config.h"

typedef struct {
    bool used;
    rvt_event_id_t id;
    rvt_event_cb_t callback;
    void *user_data;
} rvt_event_slot_t;

typedef struct {
    rvt_event_slot_t slots[RVT_EVENT_BUS_MAX_SUBSCRIBERS];
} rvt_event_bus_impl_t;

static rvt_event_bus_impl_t *rvt_event_bus_impl(rvt_event_bus_t *bus)
{
    return (rvt_event_bus_impl_t *)bus->storage;
}

static const rvt_event_bus_impl_t *rvt_event_bus_const_impl(const rvt_event_bus_t *bus)
{
    return (const rvt_event_bus_impl_t *)bus->storage;
}

/* 初始化事件总线的订阅槽位。 */
void rvt_event_bus_init(rvt_event_bus_t *bus)
{
    const size_t impl_size = sizeof(rvt_event_bus_impl_t);

    if (!bus)
        return;

    if (impl_size > sizeof(bus->storage))
        return;

    memset(bus, 0, sizeof(*bus));
}

/* 注册指定事件的订阅回调，并返回订阅句柄。 */
int rvt_event_bus_subscribe(rvt_event_bus_t *bus, rvt_event_id_t id,
                            rvt_event_cb_t callback, void *user_data)
{
    rvt_event_bus_impl_t *impl;
    int i;

    if (!bus || !callback)
        return -1;

    impl = rvt_event_bus_impl(bus);

    for (i = 0; i < RVT_EVENT_BUS_MAX_SUBSCRIBERS; i++) {
        if (impl->slots[i].used)
            continue;

        impl->slots[i].used = true;
        impl->slots[i].id = id;
        impl->slots[i].callback = callback;
        impl->slots[i].user_data = user_data;
        return i;
    }

    return -1;
}

/* 根据订阅句柄取消事件监听。 */
void rvt_event_bus_unsubscribe(rvt_event_bus_t *bus, int handle)
{
    rvt_event_bus_impl_t *impl;

    if (!bus || handle < 0 || handle >= RVT_EVENT_BUS_MAX_SUBSCRIBERS)
        return;

    impl = rvt_event_bus_impl(bus);
    memset(&impl->slots[handle], 0, sizeof(impl->slots[handle]));
}

/* 向所有匹配订阅者广播一条事件。 */
void rvt_event_bus_publish(rvt_event_bus_t *bus, rvt_event_id_t id, const void *data)
{
    const rvt_event_bus_impl_t *impl;
    rvt_event_t event;
    int i;

    if (!bus)
        return;

    impl = rvt_event_bus_const_impl(bus);
    event.id = id;
    event.data = data;

    for (i = 0; i < RVT_EVENT_BUS_MAX_SUBSCRIBERS; i++) {
        const rvt_event_slot_t *slot = &impl->slots[i];

        if (!slot->used || slot->id != id || !slot->callback)
            continue;

        slot->callback(slot->user_data, &event);
    }
}

