        return -1;
    }

    if (!rvt_time_service_timestamp_is_valid(rtc_timestamp)) {
        printf("rvt time: rtc timestamp invalid=%ld\n", (long)rtc_timestamp);
        return -1;
    }

    tv.tv_sec = rtc_timestamp;
    tv.tv_usec = 0;
    if (settimeofday(&tv, NULL) != 0) {
        printf("rvt time: seed system time from rtc failed errno=%d\n", errno);
        return -1;
