    tv.tv_usec = (suseconds_t)usec;
    if (settimeofday(&tv, NULL) != 0) {
        printf("rvt time: apply sntp time failed errno=%d\n", errno);
        return;
    }

    pthread_mutex_lock(&g_time_lock);
    first_sync = !g_time_synced;
