#include "event_bus/event_bus.h"

#ifdef __cplusplus
extern "C" {
#endif

#define RVT_AI_VOICE_EVENT_UI ((rvt_event_id_t)0xA2000001U)
#define RVT_AI_VOICE_UI_TEXT_LEN 256U

typedef enum {
    RVT_AI_VOICE_UI_STARTED = 0,
    RVT_AI_VOICE_UI_STOPPED,
    RVT_AI_VOICE_UI_ASR_TEXT,
    RVT_AI_VOICE_UI_SKILL_REPLY,
    RVT_AI_VOICE_UI_TTS_DONE,
    RVT_AI_VOICE_UI_EXIT_REQUESTED,
    RVT_AI_VOICE_UI_ERROR,
    RVT_AI_VOICE_UI_LISTENING,
    RVT_AI_VOICE_UI_VEHICLE_SELFCHECK,
    RVT_AI_VOICE_UI_BATTERY_REMINDER,
} rvt_ai_voice_ui_event_type_t;

typedef struct {
    rvt_ai_voice_ui_event_type_t type;
    int result;
    char text[RVT_AI_VOICE_UI_TEXT_LEN];
} rvt_ai_voice_ui_event_t;

#ifndef AI_VOICE_REALTIME_AFTER_TTS_CB_T_DEFINED
#define AI_VOICE_REALTIME_AFTER_TTS_CB_T_DEFINED
typedef void (*ai_voice_realtime_after_tts_cb_t)(void *user_data);
#endif

/**
 * 功能: 初始化 AI 语音适配层。
 * @param event_bus 全局事件总线指针。
 * @return 0 表示成功，负值表示事件订阅失败。
 * @note event_bus 生命周期必须覆盖 ai_voice 模块运行周期。
 */
int ai_voice_init(rvt_event_bus_t *event_bus);
/**
 * 功能: 启动语音采集和实时对话。
 * @return 0 表示启动成功，负值表示实时语音线程启动失败。
 * @note 底层会直连火山云实时语音 WebSocket。
 */
int ai_voice_start_capture(void);
/**
 * 功能: 停止语音采集和实时对话。
 * @return 0 表示已停止，负值表示停止过程异常。
 * @note 停止后可重新调用 ai_voice_start_capture。
 */
int ai_voice_stop_capture(void);
/**
 * 功能: 播报一段文本。
 * @param text 待播报文本。
 * @return 0 表示已提交 TTS，负值表示实时语音未运行或发送失败。
 * @note 该接口通过火山云 CHAT_TTS_TEXT 事件生成语音。
 */
int ai_voice_speak_text(const char *text);
/**
 * 功能: 播报一段文本，播报结束后停止实时语音。
 * @param text 待播报文本。
 * @return 0 表示已提交 TTS，负值表示参数错误、未运行或发送失败。
 * @note 主要用于导航等流程切走语音助手前的最后提示。
 */
int ai_voice_speak_text_then_stop(const char *text);
/**
 * 功能: 启动实时语音线程。
 * @return 0 表示成功，负值表示初始化失败。
 * @note 兼容上层直接调用实时语音接口。
 */
int ai_voice_realtime_start(void);
/**
 * 功能: 停止实时语音线程。
 * @return 0 表示成功，负值表示停止异常。
 * @note 兼容上层直接调用实时语音接口。
 */
int ai_voice_realtime_stop(void);
/**
 * 功能: 发送文本给云端对话。
 * @param text 用户文本。
 * @return 0 表示成功，负值表示未连接或发送失败。
 * @note 主要用于 shell 调试。
 */
int ai_voice_realtime_send_text(const char *text);
/**
 * 功能: 发送文本给云端 TTS。
 * @param text 待播报文本。
 * @return 0 表示成功，负值表示未连接或发送失败。
 * @note 主要用于本地 Skill 播报和 shell 调试。
 */
int ai_voice_realtime_send_tts_text(const char *text);
/**
 * 功能: 通过当前火山云会话发送 TTS 文本，播报后停止实时语音。
 * @param text 待播报文本。
 * @return 0 表示成功，负值表示未连接或发送失败。
 * @note 供 ai_voice_speak_text_then_stop 复用。
 */
int ai_voice_realtime_send_tts_text_then_stop(const char *text);
/**
 * 功能: 安排一个动作在下一段本地 TTS 播报结束后执行。
 * @param cb TTS 结束后的执行回调。
 * @param user_data 回调上下文，由调用方分配。
 * @param cleanup 动作被替换或取消时释放 user_data 的回调，可为 NULL。
 * @return 0 表示已安排，负值表示参数错误或实时语音未运行。
 * @note 新动作会替换尚未执行的旧动作；正常执行后不会再调用 cleanup。
 */
int ai_voice_realtime_schedule_after_local_tts(ai_voice_realtime_after_tts_cb_t cb,
                                               void *user_data,
                                               ai_voice_realtime_after_tts_cb_t cleanup);
/**
 * 功能: 查询实时语音线程运行状态。
 * @return true 表示运行中，false 表示未运行。
 * @note 不等同于云端连接状态。
 */
bool ai_voice_realtime_is_running(void);
/**
 * 功能: 发布 AI 语音 UI 状态事件。
 * @param type UI 事件类型。
 * @param result 关联结果码，成功时通常为 0。
 * @param text 可显示文本，可为 NULL。
 * @return 无。
 * @note 供实时语音内部和 Skill 层解耦通知应用 UI。
 */
void ai_voice_publish_ui_event(rvt_ai_voice_ui_event_type_t type,
                               int result,
                               const char *text);

#ifdef __cplusplus
}
#endif

#endif /* __AI_VOICE_H__ */

