+
+int rvt_event_bus_subscribe(rvt_event_bus_t *bus, rvt_event_id_t id,
+                            rvt_event_cb_t callback, void *user_data)
+{
+    scooter_event_bus_impl_t *impl;
+    int i;
+
+    if (bus == NULL || callback == NULL)
+        return -EINVAL;
+
+    impl = scooter_event_bus_impl(bus);
+    for (i = 0; i < RVT_EVENT_BUS_MAX_SUBSCRIBERS; i++) {
+        if (impl->slots[i].used)
+            continue;
+
+        impl->slots[i].used = true;
+        impl->slots[i].id = id;
+        impl->slots[i].callback = callback;
+        impl->slots[i].user_data = user_data;
+        return i;
+    }
+
+    return -ENOMEM;
+}
+
+void rvt_event_bus_unsubscribe(rvt_event_bus_t *bus, int handle)
+{
+    scooter_event_bus_impl_t *impl;
+
+    if (bus == NULL || handle < 0 ||
+        handle >= RVT_EVENT_BUS_MAX_SUBSCRIBERS)
+        return;
+
+    impl = scooter_event_bus_impl(bus);
+    memset(&impl->slots[handle], 0, sizeof(impl->slots[handle]));
+}
+
+void rvt_event_bus_publish(rvt_event_bus_t *bus, rvt_event_id_t id,
+                           const void *data)
+{
+    scooter_event_bus_impl_t *impl;
+    rvt_event_t event;
+    int i;
+
+    if (bus == NULL)
+        return;
+
+    impl = scooter_event_bus_impl(bus);
+    event.id = id;
+    event.data = data;
+    for (i = 0; i < RVT_EVENT_BUS_MAX_SUBSCRIBERS; i++) {
+        if (!impl->slots[i].used || impl->slots[i].id != id ||
+            impl->slots[i].callback == NULL)
+            continue;
+
+        impl->slots[i].callback(impl->slots[i].user_data, &event);
