#define FAKE_IMAGE_PARSE(fake_name, pwidth, pheight, pblend, pcolor) \
        fake_image_parse(fake_name, pwidth, pheight, pblend, pcolor)

static inline void fake_image_parse(char *fake_name, int *width,
                                    int *height, int *blend,
                                    unsigned int *color)
{
    char *cur_ptr;
    char *pos_ptr;
    cur_ptr = fake_name + 3;
