static void scooter_navigation_get_time_text(char *buffer, size_t buffer_size)
{
    time_t now;
    struct tm tm_now;

    if (!buffer || buffer_size == 0U)
        return;

    if (!rvt_time_service_is_ready()) {
        lv_snprintf(buffer, buffer_size, "--:--");
        return;
    }

    now = time(NULL);
    if (localtime_r(&now, &tm_now) == NULL) {
        lv_snprintf(buffer, buffer_size, "--:--");
        return;
    }

    strftime(buffer, buffer_size, "%H:%M", &tm_now);
}

