static void scooter_shell_view_request_nav_work(scooter_shell_view_t *view,
                                                scooter_shell_nav_work_action_t action)
{
    rt_thread_t thread;
    rt_base_t level;
    bool worker_running;

    if (!view || action == SCOOTER_SHELL_NAV_WORK_NONE)
        return;

    level = rt_hw_interrupt_disable();
    view->nav_worker_action = (uint8_t)action;
    view->nav_worker_seq++;
    worker_running = view->nav_worker_running;
    if (!worker_running)
        view->nav_worker_running = true;
    rt_hw_interrupt_enable(level);

    if (worker_running)
        return;

    thread = rt_thread_create("navwork",
                              scooter_shell_view_nav_worker_entry,
                              view,
                              SCOOTER_SHELL_NAV_WORKER_STACK,
                              SCOOTER_SHELL_NAV_WORKER_PRIORITY,
                              20);
    if (thread) {
        rt_thread_startup(thread);
    } else {
        level = rt_hw_interrupt_disable();
        view->nav_worker_running = false;
        view->nav_worker_busy = false;
        rt_hw_interrupt_enable(level);
        SCOOTER_SHELL_LOG("failed to create navigation worker");
    }
}

static void scooter_shell_view_nav_worker_entry(void *parameter)
{
    scooter_shell_view_t *view = parameter;

    if (!view)
        return;

    for (;;) {
        uint32_t seq;
        uint8_t action;
        rt_base_t level;

        level = rt_hw_interrupt_disable();
        if (view->nav_worker_handled_seq == view->nav_worker_seq) {
            view->nav_worker_busy = false;
            view->nav_worker_running = false;
            rt_hw_interrupt_enable(level);
            return;
        }
        view->nav_worker_busy = true;
        seq = view->nav_worker_seq;
        action = view->nav_worker_action;
        view->nav_worker_handled_seq = seq;
        rt_hw_interrupt_enable(level);

        switch ((scooter_shell_nav_work_action_t)action) {
        case SCOOTER_SHELL_NAV_WORK_START_DISPLAY:
            if (rvt_map_show_location() < 0)
                SCOOTER_SHELL_LOG("navigation display start failed");
            break;
        case SCOOTER_SHELL_NAV_WORK_STOP:
            rvt_wifi_display_stop();
            break;
        default:
            break;
        }
    }
}

