#include "scooter_page_manager.h"

/* 初始化页面管理器，默认从主页开始。 */
void scooter_page_manager_init(scooter_page_manager_t *manager)
{
    if (!manager)
        return;

    for (int index = 0; index < SCOOTER_PAGE_COUNT; index++)
        manager->containers[index] = NULL;

    manager->active_page = SCOOTER_PAGE_HOME;
    manager->previous_page = SCOOTER_PAGE_HOME;
}

/* 一级页面根容器统一做成全屏透明画布，实际内容由各 page 自己绘制。 */
lv_obj_t *scooter_page_manager_create_container(lv_obj_t *parent,
                                                lv_coord_t width,
                                                lv_coord_t height)
{
    lv_obj_t *container = lv_obj_create(parent);

    lv_obj_remove_style_all(container);
    lv_obj_set_size(container, width, height);
    lv_obj_align(container, LV_ALIGN_CENTER, 0, 0);
    lv_obj_set_style_bg_opa(container, LV_OPA_0, 0);
    lv_obj_set_style_border_width(container, 0, 0);
    lv_obj_set_style_pad_all(container, 0, 0);
    lv_obj_clear_flag(container, LV_OBJ_FLAG_CLICKABLE);
    lv_obj_clear_flag(container, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_scrollbar_mode(container, LV_SCROLLBAR_MODE_OFF);
    return container;
}

/* 注册页面根容器，后续 show 时按 page_id 查找。 */
void scooter_page_manager_register(scooter_page_manager_t *manager,
                                   scooter_page_id_t page_id,
                                   lv_obj_t *container)
{
    if (!manager || page_id >= SCOOTER_PAGE_COUNT)
        return;

    manager->containers[page_id] = container;
}

/* 显示目标页面并隐藏其他页面，同时记录上一页，供返回逻辑使用。 */
void scooter_page_manager_show(scooter_page_manager_t *manager,
                               scooter_page_id_t page_id)
{
    if (!manager || page_id >= SCOOTER_PAGE_COUNT)
        return;

    if (manager->active_page != page_id)
        manager->previous_page = manager->active_page;

    for (int index = 0; index < SCOOTER_PAGE_COUNT; index++) {
        lv_obj_t *container = manager->containers[index];

        if (!container)
            continue;

        if (index == page_id) {
            lv_obj_clear_flag(container, LV_OBJ_FLAG_HIDDEN);
            lv_obj_set_style_opa(container, LV_OPA_COVER, 0);
            lv_obj_move_foreground(container);
        } else {
            lv_obj_add_flag(container, LV_OBJ_FLAG_HIDDEN);
        }
    }

    manager->active_page = page_id;
}

