static void *scooter_ui_thread_entry(void *parameter)
{
    rt_thread_t thread = (rt_thread_t)parameter;

    if (thread != NULL && thread->entry != NULL)
        thread->entry(thread->parameter);

    return NULL;
}

rt_thread_t rt_thread_create(const char *name,
                             void (*entry)(void *parameter),
                             void *parameter,
                             size_t stack_size,
                             int priority,
                             int tick)
{
    rt_thread_t thread;

    (void)name;
    (void)stack_size;
    (void)priority;
    (void)tick;

    if (entry == NULL)
        return NULL;

    thread = (rt_thread_t)calloc(1, sizeof(*thread));
    if (thread == NULL)
        return NULL;

    thread->entry = entry;
    thread->parameter = parameter;
    return thread;
}

int rt_thread_startup(rt_thread_t thread)
{
    int ret;

    if (thread == NULL)
        return -EINVAL;

    ret = pthread_create(&thread->thread, NULL,
                         scooter_ui_thread_entry, thread);
    if (ret != 0)
        return -ret;

    pthread_detach(thread->thread);
    return 0;
}

