                                            size_t *count,
                                            const struct ui_demo_wifi_ap *ap)
{
  size_t i;

  for (i = 0; i < *count; i++)
    {
      if (strcmp(aps[i].ssid, ap->ssid) == 0)
        {
          if (ap->rssi > aps[i].rssi)
            {
              aps[i] = *ap;
            }

          return;
        }
    }

  if (*count < UI_DEMO_WIFI_MAX_APS)
    {
      aps[*count] = *ap;
      (*count)++;
    }
}

