  base = strrchr(cmdline, '/');
  base = base == NULL ? cmdline : base + 1;
  end = base;
  while (*end != '\0' && *end != ' ' && *end != '\t' &&
         *end != '\r' && *end != '\n')
    {
      end++;
    }

  name_len = strlen(name);
  base_len = (size_t)(end - base);
  return base_len == name_len && strncmp(base, name, name_len) == 0;
}

