/* 初始化主控制器，并绑定界面按钮事件。 */
void scooter_main_controller_init(scooter_main_controller_t *controller,
                                  scooter_model_t *model,
                                  scooter_main_view_t *view,
                                  scooter_board_service_t *board_service)
{
    if (!controller)
        return;

    controller->model = model;
    controller->view = view;
    controller->board_service = board_service;
    controller->refresh_timer = 0;

    if (view) {
        lv_obj_t *mode_button = scooter_main_view_get_mode_button(view);
        lv_obj_t *light_button = scooter_main_view_get_light_button(view);
        lv_obj_t *boost_button = scooter_main_view_get_boost_button(view);

        if (mode_button) {
            lv_obj_add_event_cb(mode_button, scooter_mode_btn_cb,
                                LV_EVENT_CLICKED, controller);
        }
        if (light_button) {
            lv_obj_add_event_cb(light_button, scooter_light_btn_cb,
                                LV_EVENT_CLICKED, controller);
        }
        if (boost_button) {
            lv_obj_add_event_cb(boost_button, scooter_boost_btn_cb,
                                LV_EVENT_CLICKED, controller);
        }
    }
}

/* 启动车辆状态刷新定时器。 */
void scooter_main_controller_start(scooter_main_controller_t *controller)
{
    if (!controller || controller->refresh_timer)
        return;

    controller->refresh_timer = lv_timer_create(scooter_refresh_timer_cb,
                                                SCOOTER_DEMO_REFRESH_PERIOD_MS,
                                                controller);
}

/* 停止车辆状态刷新定时器。 */
void scooter_main_controller_stop(scooter_main_controller_t *controller)
{
    if (!controller || !controller->refresh_timer)
        return;

    lv_timer_del(controller->refresh_timer);
    controller->refresh_timer = 0;
}

void scooter_main_controller_start_drive_demo(scooter_main_controller_t *controller)
{
    scooter_state_t next_state;

    if (!controller || !controller->model || !controller->board_service)
        return;

    scooter_board_service_start_demo(controller->board_service);
    next_state = *scooter_model_get_state(controller->model);
    scooter_board_service_step(controller->board_service, &next_state);
    scooter_model_set_state(controller->model, &next_state);
}

void scooter_main_controller_stop_drive_demo(scooter_main_controller_t *controller)
{
    scooter_state_t next_state;

    if (!controller || !controller->model || !controller->board_service)
        return;

    scooter_board_service_stop_demo(controller->board_service);
    next_state = *scooter_model_get_state(controller->model);
    scooter_board_service_step(controller->board_service, &next_state);
    scooter_model_set_state(controller->model, &next_state);
}

/* 定时拉取板级状态并同步到模型层。 */
static void scooter_refresh_timer_cb(lv_timer_t *timer)
{
    scooter_main_controller_t *controller = timer->user_data;
    scooter_state_t next_state;

    if (!controller || !controller->model || !controller->board_service)
        return;

    next_state = *scooter_model_get_state(controller->model);
    scooter_board_service_step(controller->board_service, &next_state);
    scooter_model_set_state(controller->model, &next_state);
}

/* 处理模式切换按钮点击事件。 */
static void scooter_mode_btn_cb(lv_event_t *e)
{
    scooter_main_controller_t *controller = lv_event_get_user_data(e);

    if (!controller || lv_event_get_code(e) != LV_EVENT_CLICKED)
        return;

    scooter_model_cycle_drive_mode(controller->model);
}

/* 处理灯光按钮点击事件。 */
static void scooter_light_btn_cb(lv_event_t *e)
{
    scooter_main_controller_t *controller = lv_event_get_user_data(e);

    if (!controller || lv_event_get_code(e) != LV_EVENT_CLICKED)
        return;

    scooter_model_toggle_headlight(controller->model);
}

/* 处理加速按钮点击事件并提升当前车速。 */
static void scooter_boost_btn_cb(lv_event_t *e)
{
    scooter_main_controller_t *controller = lv_event_get_user_data(e);
    scooter_state_t next_state;
    uint16_t speed_limit;

    if (!controller || !controller->model || lv_event_get_code(e) != LV_EVENT_CLICKED)
        return;

    next_state = *scooter_model_get_state(controller->model);
    speed_limit = SCOOTER_DEMO_MAX_SPEED_KMH;

    if (next_state.speed_kmh + 5U >= speed_limit)
        next_state.speed_kmh = speed_limit;
    else
        next_state.speed_kmh += 5U;

    next_state.controller_online = true;
    next_state.gear[0] = next_state.speed_kmh == 0U ? 'P' : 'D';
    next_state.gear[1] = '\0';
    next_state.driver_demo_effect = SCOOTER_DRIVER_DEMO_EFFECT_NONE;
    next_state.driver_demo_running = false;
    scooter_model_set_state(controller->model, &next_state);
}

