#if defined(RIVOTEK_QRCODE_SERVICE)
/* 按指定路径和字号创建二维码弹层运行时字体。 */
static lv_font_t *scooter_app_qrcode_create_runtime_font(const char *path,
                                                         uint32_t size)
{
#if LV_USE_FREETYPE
    return lv_freetype_font_create(path,
                                   LV_FREETYPE_FONT_RENDER_MODE_BITMAP,
                                   size,
                                   LV_FREETYPE_FONT_STYLE_NORMAL);
#else
    LV_UNUSED(path);
    LV_UNUSED(size);
    return NULL;
#endif
}

/* 初始化二维码弹层使用的 CJK fallback 字体。 */
static void scooter_app_qrcode_fonts_init(void)
{
    if (g_qrcode_fonts_ready)
        return;

    g_qrcode_font_20_cjk = lv_font_montserrat_20;
    g_qrcode_font_28_cjk = lv_font_montserrat_28;
    g_qrcode_font_40_cjk = lv_font_montserrat_40;
    g_qrcode_font_20_cjk.fallback = &lv_font_simsun_16_cjk;
    g_qrcode_font_28_cjk.fallback = &lv_font_simsun_16_cjk;
    g_qrcode_font_40_cjk.fallback = &lv_font_simsun_16_cjk;
    g_qrcode_font_cn_16 =
        scooter_app_qrcode_create_runtime_font(LVGL_FONT_PATH(DroidSansFallback.ttf),
                                               16);
    g_qrcode_font_cn_20 =
        scooter_app_qrcode_create_runtime_font(LVGL_FONT_PATH(DroidSansFallback.ttf),
                                               20);
    g_qrcode_font_cn_28 =
        scooter_app_qrcode_create_runtime_font(LVGL_FONT_PATH(DroidSansFallback.ttf),
                                               28);
    g_qrcode_font_cn_40 =
        scooter_app_qrcode_create_runtime_font(LVGL_FONT_PATH(DroidSansFallback.ttf),
                                               40);
    g_qrcode_fonts_ready = true;
}

/* 在 LVGL UI 线程中驱动二维码弹层 show/hide 和倒计时。 */
static void scooter_app_qrcode_poll_timer_cb(lv_timer_t *timer)
{
    (void)timer;
    rvt_qrcode_poll();
}

/* 主界面就绪后初始化通用二维码服务和 WiFi 配网桥接。 */
static void scooter_app_init_qrcode(scooter_app_ctx_t *app)
{
    rvt_qrcode_ui_metrics_t qr_ui;

    if (!app || !app->shell_view.screen)
        return;

    scooter_app_qrcode_fonts_init();
    memset(&qr_ui, 0, sizeof(qr_ui));
    qr_ui.disp_w = SCOOTER_DEMO_SCREEN_WIDTH;
    qr_ui.disp_h = SCOOTER_DEMO_SCREEN_HEIGHT;
    qr_ui.font_16 = g_qrcode_font_cn_16 ?
                    g_qrcode_font_cn_16 :
                    &lv_font_simsun_16_cjk;
    qr_ui.font_20 = g_qrcode_font_cn_20 ?
                    g_qrcode_font_cn_20 :
                    &g_qrcode_font_20_cjk;
    qr_ui.font_28 = g_qrcode_font_cn_28 ?
                    g_qrcode_font_cn_28 :
                    &g_qrcode_font_28_cjk;
    qr_ui.font_40 = g_qrcode_font_cn_40 ?
                    g_qrcode_font_cn_40 :
                    &g_qrcode_font_40_cjk;

    rvt_qrcode_init(app->shell_view.screen, &qr_ui);
#if defined(RIVOTEK_PROVISIONING_SERVICE)
    if (rvt_provisioning_qrcode_bridge_init() < 0)
        printf("scooter_demo: failed to init provisioning QR bridge\n");
#endif

    if (!app->qrcode_poll_timer)
        app->qrcode_poll_timer = lv_timer_create(scooter_app_qrcode_poll_timer_cb,
                                                 SCOOTER_QRCODE_POLL_MS,
                                                 app);
}
#endif

/* 在启动页销毁时清空对象引用，避免残留悬挂指针。 */
static void scooter_app_boot_screen_event_cb(lv_event_t *e)
{
    scooter_app_ctx_t *app = lv_event_get_user_data(e);

    if (!app || lv_event_get_code(e) != LV_EVENT_DELETE)
        return;

    app->boot_screen = NULL;
    app->boot_gif = NULL;
}

/* 启动 GIF 播放完成后再创建并切入主页面，避免主页资源抢占首屏。 */
static void scooter_app_boot_gif_event_cb(lv_event_t *e)
{
    scooter_app_ctx_t *app = lv_event_get_user_data(e);

    if (!app || lv_event_get_code(e) != LV_EVENT_READY)
        return;

    app->boot_anim_finished = true;
    scooter_app_show_main_ui(app);
}

/* 检查主界面资源所在文件系统是否已经挂载完成。 */
static bool scooter_app_storage_ready(void)
{
#if defined(KERNEL_RTTHREAD)
    struct dfs_filesystem *fs = dfs_filesystem_lookup(LVGL_STORAGE_PATH);

    if (fs && strncmp(LVGL_STORAGE_PATH, fs->path, 3) == 0)
        return true;

    return false;
#else

