    return gif_obj && gif_obj->gif != NULL;
#else
    LV_UNUSED(gif_img);
    return false;
#endif
}

static lv_obj_t *scooter_main_view_ensure_home_gif(scooter_main_view_t *view)
{
    if (!view || !view->home_gif_slot)
        return NULL;

    if (!view->home_gif_img) {
        view->home_gif_img = lv_gif_create(view->home_gif_slot);
        if (view->home_gif_img)
            lv_obj_center(view->home_gif_img);
    }

    return view->home_gif_img;
}

static void scooter_main_view_delete_home_gif(scooter_main_view_t *view)
{
    if (!view || !view->home_gif_img)
        return;

    if (!scooter_main_view_home_gif_loaded(view->home_gif_img)) {
        lv_obj_add_flag(view->home_gif_img, LV_OBJ_FLAG_HIDDEN);
        return;
    }

    lv_obj_delete(view->home_gif_img);
    view->home_gif_img = NULL;
}

/* 设置首页中心区域的待机动画资源。 */
static void scooter_main_view_set_idle_gif(scooter_main_view_t *view, uint8_t gif_index)
{
    lv_obj_t *gif_img;

    if (!view)
        return;

