/* 创建纯开机页，先只显示 GIF，避免主页大图参与首屏绘制。 */
static void scooter_app_show_boot_screen(scooter_app_ctx_t *app)
{
    lv_obj_t *screen;
    lv_obj_t *gif;

    if (!app)
        return;

    screen = lv_obj_create(NULL);
    lv_obj_remove_style_all(screen);
    lv_obj_clear_flag(screen, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(screen, SCOOTER_DEMO_SCREEN_WIDTH, SCOOTER_DEMO_SCREEN_HEIGHT);
    lv_obj_set_style_bg_color(screen, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, 0);
    lv_obj_add_event_cb(screen, scooter_app_boot_screen_event_cb, LV_EVENT_DELETE, app);

    gif = lv_gif_create(screen);
    if (!gif) {
        lv_obj_delete(screen);
        scooter_app_show_main_ui(app);
        return;
    }

    lv_gif_set_src(gif, &scooter_boot_gif_asset);
    if (!lv_image_get_src(gif)) {
        lv_obj_delete(screen);
        scooter_app_show_main_ui(app);
        return;
    }
    lv_obj_center(gif);
    lv_gif_set_loop_count(gif, 1);
    lv_obj_add_event_cb(gif, scooter_app_boot_gif_event_cb, LV_EVENT_READY, app);

    app->boot_screen = screen;
    app->boot_gif = gif;

    lv_scr_load(screen);
}

