                                   const char *input_path)
{
  lv_nuttx_dsc_t dsc;

  memset(&g_lvgl_result, 0, sizeof(g_lvgl_result));
  lv_nuttx_dsc_init(&dsc);
  dsc.fb_path = fb_path;
  dsc.input_path = input_path;

  lv_nuttx_init(&dsc, &g_lvgl_result);
  if (g_lvgl_result.disp == NULL)
    {
      return -ENODEV;
    }

  return 0;
