      memset(&g_lvgl_result, 0, sizeof(g_lvgl_result));
      syslog(LOG_ERR, "%s: display init failed: %d\n", LVGL_APP_TAG, ret);
      return ret;
    }

  g_lvgl_ready = true;

  if (input != NULL && input[0] != '\0' && g_lvgl_result.indev == NULL)
    {
      syslog(LOG_WARNING, "%s: input init deferred: %s\n",
             LVGL_APP_TAG, input);
    }

  return 0;
}

