int lvgl_app_init(void)
{
  int ret;

  ret = lvgl_app_init_display();
  if (ret < 0)
    {
      return ret;
    }

  (void)lvgl_app_backlight_set_percent(
    CONFIG_LVGL_APP_BACKLIGHT_DEFAULT_PERCENT);
  lvgl_app_create_ui();
  syslog(LOG_INFO, "%s: ready\n", LVGL_APP_TAG);
