/* 检查主界面资源所在文件系统是否已经挂载完成。 */
static bool scooter_app_storage_ready(void)
{
#if defined(KERNEL_RTTHREAD)
    struct dfs_filesystem *fs = dfs_filesystem_lookup(LVGL_STORAGE_PATH);

    if (fs && strncmp(LVGL_STORAGE_PATH, fs->path, 3) == 0)
        return true;

    return false;
#else
    return true;
#endif
}

/* 文件系统就绪后再切换到主页面，避免首页资源加载失败。 */
static void scooter_app_storage_poll_timer_cb(lv_timer_t *timer)
{
    scooter_app_ctx_t *app = timer ? timer->user_data : NULL;

    if (!app || !scooter_app_storage_ready())
        return;

    if (app->storage_poll_timer) {
        lv_timer_del(app->storage_poll_timer);
        app->storage_poll_timer = NULL;
    }

    if (app->boot_anim_finished)
        scooter_app_show_main_ui(app);
}

/* 在启动动画播放期间异步等待资源文件系统就绪。 */
static void scooter_app_ensure_storage_poll(scooter_app_ctx_t *app)
{
    if (!app || app->storage_poll_timer)
        return;

    app->storage_poll_timer = lv_timer_create(scooter_app_storage_poll_timer_cb,
                                              SCOOTER_STORAGE_POLL_MS,
                                              app);
}

/* 延后初始化主页面和控制器，确保开机动画先完整显示。 */
static void scooter_app_prepare_main_ui(scooter_app_ctx_t *app)
{
    if (!app || app->main_ui_initialized)
        return;

    /* 主 UI 改为统一 shell，由它内部接管页面管理和按键分发。 */
    scooter_shell_view_init(&app->shell_view,
                            &app->event_bus,
                            scooter_model_get_state(&app->model));
    scooter_main_controller_init(&app->main_controller,
                                 &app->model,
                                 scooter_shell_view_get_main_view(&app->shell_view),
                                 &app->board_service);
    scooter_shell_view_set_main_controller(&app->shell_view,
                                           &app->main_controller);
#if defined(RIVOTEK_QRCODE_SERVICE)
    scooter_app_init_qrcode(app);
#endif
    app->main_ui_initialized = true;
}

/* 切入主页并启动业务更新，随后回收开机页。 */
static void scooter_app_show_main_ui(scooter_app_ctx_t *app)
{
    if (!app)
        return;

    if (!scooter_app_storage_ready()) {
        scooter_app_ensure_storage_poll(app);
        return;
    }

    scooter_app_prepare_main_ui(app);
    if (!app->shell_view.screen)
        return;

    /* boot 结束后切入 shell，由 shell 决定当前显示的一级页面。 */
    scooter_shell_view_show(&app->shell_view);
    rvt_display_ui_refresh_now();

    if (app->boot_screen && app->boot_screen != app->shell_view.screen)
        lv_obj_delete_async(app->boot_screen);

    if (!app->main_ui_started) {
        scooter_main_controller_start(&app->main_controller);
        app->main_ui_started = true;
    }
}

/* 创建纯开机页，先只显示 GIF，避免主页大图参与首屏绘制。 */
static void scooter_app_show_boot_screen(scooter_app_ctx_t *app)
{
    lv_obj_t *screen;
    lv_obj_t *gif;

    if (!app)
        return;

    screen = lv_obj_create(NULL);
    lv_obj_remove_style_all(screen);
    lv_obj_clear_flag(screen, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(screen, SCOOTER_DEMO_SCREEN_WIDTH, SCOOTER_DEMO_SCREEN_HEIGHT);
    lv_obj_set_style_bg_color(screen, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, 0);
    lv_obj_add_event_cb(screen, scooter_app_boot_screen_event_cb, LV_EVENT_DELETE, app);

    gif = lv_gif_create(screen);
    if (!gif) {
        lv_obj_delete(screen);
        scooter_app_show_main_ui(app);
        return;
    }

    lv_gif_set_src(gif, &scooter_boot_gif_asset);
    if (!lv_image_get_src(gif)) {
        lv_obj_delete(screen);
        scooter_app_show_main_ui(app);
        return;
    }
    lv_obj_center(gif);
    lv_obj_add_event_cb(gif, scooter_app_boot_gif_event_cb, LV_EVENT_READY, app);

    app->boot_screen = screen;
    app->boot_gif = gif;
    scooter_app_cancel_boot_fallback_timer(app);
    app->boot_fallback_timer = lv_timer_create(scooter_app_boot_fallback_timer_cb,
                                               SCOOTER_BOOT_GIF_FALLBACK_MS,
                                               app);
    if (app->boot_fallback_timer)
        lv_timer_set_repeat_count(app->boot_fallback_timer, 1);

    lv_scr_load(screen);
}

/* 初始化应用上下文，并启动主界面和控制器。 */
void scooter_app_init(void)
{
    scooter_state_t initial_state;

    if (rvt_display_init() < 0)
        return;
    if (rvt_input_init() < 0)
        printf("scooter_demo: failed to start input service\n");

    if (g_scooter_app.initialized) {
        if (g_scooter_app.main_ui_initialized)
            scooter_app_show_main_ui(&g_scooter_app);
        else
            scooter_app_show_boot_screen(&g_scooter_app);
        lv_obj_move_foreground(view->speed_unit_value);
}

static void scooter_main_view_show_center_media(scooter_main_view_t *view,
                                                const char *gif_path,
                                                const char *fallback_text)
{
    lv_obj_t *gif_img = NULL;

    if (!view || !view->home_gif_slot)
        return;

    lv_obj_clear_flag(view->home_gif_slot, LV_OBJ_FLAG_HIDDEN);

    if (gif_path) {
        gif_img = scooter_main_view_ensure_home_gif(view);
        if (gif_img) {
            lv_gif_set_src(gif_img, gif_path);
            if (scooter_main_view_home_gif_loaded(gif_img)) {
                lv_obj_center(gif_img);
                lv_obj_clear_flag(gif_img, LV_OBJ_FLAG_HIDDEN);
                if (view->home_effect_label)
                    lv_obj_add_flag(view->home_effect_label, LV_OBJ_FLAG_HIDDEN);
                return;
            }
        }
    }

    if (view->home_gif_img)
        lv_obj_add_flag(view->home_gif_img, LV_OBJ_FLAG_HIDDEN);

    if (!view->home_effect_label)
        return;

    scooter_set_label_text(view->home_effect_label,
                           fallback_text ? fallback_text : "");
    if (fallback_text && fallback_text[0] != '\0') {
        lv_obj_clear_flag(view->home_effect_label, LV_OBJ_FLAG_HIDDEN);
        lv_obj_center(view->home_effect_label);
    } else {
        scooter_main_view_hide_center_media(view);
    }
}

