static bool scooter_main_view_home_gif_loaded(lv_obj_t *gif_img)
{
#if LV_USE_GIF
    const lv_gif_t *gif_obj = (const lv_gif_t *)gif_img;

    if (!gif_obj)
        return false;

#if !LV_USE_CUSTOM_GIF
    {
        const scooter_lv_gifdec_ctx_t *dec_ctx =
            (const scooter_lv_gifdec_ctx_t *)gif_obj->dec_ctx;

        return dec_ctx && dec_ctx->gif != NULL;
    }
#else
    return lv_image_get_src(gif_img) != NULL;
#endif
#else
    LV_UNUSED(gif_img);
