{
    const char *current_text;

    if (!label || !text)
        return;

    current_text = lv_label_get_text(label);
    if (current_text && strcmp(current_text, text) == 0)
        return;

    scooter_music_delete_label_animations(label);
    lv_label_set_text(label, text);
}

