/* 创建一个透明的可点击热区。 */
static lv_obj_t *scooter_create_touch_area(lv_obj_t *parent, lv_coord_t width, lv_coord_t height)
{
    lv_obj_t *touch = lv_obj_create(parent);

    lv_obj_remove_style_all(touch);
    lv_obj_set_size(touch, width, height);
    lv_obj_add_flag(touch, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_IGNORE_LAYOUT);
    lv_obj_set_style_bg_opa(touch, LV_OPA_0, 0);
    lv_obj_set_style_border_width(touch, 0, 0);
    lv_obj_clear_flag(touch, LV_OBJ_FLAG_SCROLLABLE);
    return touch;
}

/* 创建一个无背景无边框的透明容器。 */
static lv_obj_t *scooter_create_transparent_container(lv_obj_t *parent, lv_coord_t width, lv_coord_t height)
{
    lv_obj_t *cont = lv_obj_create(parent);

    lv_obj_remove_style_all(cont);
    lv_obj_set_size(cont, width, height);
    lv_obj_set_style_bg_opa(cont, LV_OPA_0, 0);
    lv_obj_set_style_border_width(cont, 0, 0);
    lv_obj_clear_flag(cont, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_scrollbar_mode(cont, LV_SCROLLBAR_MODE_OFF);
    return cont;
}

