/* 按键线程和 LVGL 线程会同时访问队列，临界区只保护 head/tail 和单条消息。 */
static bool scooter_shell_view_try_enqueue_input(scooter_shell_view_t *view,
                                                 rvt_input_key_t key,
                                                 rvt_input_event_t event)
{
    bool queued = false;
    uint8_t next_head;
#if (SCOOTER_DEMO_HAL_SYSTEM == SCOOTER_DEMO_HAL_SYSTEM_RTTHREAD)
    rt_base_t level = rt_hw_interrupt_disable();
#endif

    if (view) {
        next_head = (uint8_t)((view->input_head + 1U) % SCOOTER_SHELL_QUEUE_CAPACITY);
        if (next_head != view->input_tail) {
            view->input_queue[view->input_head].key = key;
            view->input_queue[view->input_head].event = event;
            view->input_head = next_head;
            queued = true;
        }
    }

#if (SCOOTER_DEMO_HAL_SYSTEM == SCOOTER_DEMO_HAL_SYSTEM_RTTHREAD)
    rt_hw_interrupt_enable(level);
#endif
    return queued;
}

/* 出队时同样只在拷贝单条消息时关中断，避免把 LVGL 事件处理包进临界区。 */
static bool scooter_shell_view_try_dequeue_input(scooter_shell_view_t *view,
                                                 scooter_shell_input_msg_t *msg)
{
    bool has_msg = false;
#if (SCOOTER_DEMO_HAL_SYSTEM == SCOOTER_DEMO_HAL_SYSTEM_RTTHREAD)
    rt_base_t level = rt_hw_interrupt_disable();
#endif

    if (view && msg && view->input_tail != view->input_head) {
        *msg = view->input_queue[view->input_tail];
        view->input_tail = (uint8_t)((view->input_tail + 1U) % SCOOTER_SHELL_QUEUE_CAPACITY);
        has_msg = true;
    }

#if (SCOOTER_DEMO_HAL_SYSTEM == SCOOTER_DEMO_HAL_SYSTEM_RTTHREAD)
    rt_hw_interrupt_enable(level);
#endif
    return has_msg;
}

/* 主页和导航页共用侧边栏焦点，切回任一页时都保持一致。 */
static void scooter_shell_view_apply_sidebar_focus(scooter_shell_view_t *view)
{
    if (!view)
        return;

    scooter_main_view_set_sidebar_focus(&view->main_view,
                                        (scooter_page_id_t)view->sidebar_focus_index);
    scooter_navigation_view_set_sidebar_focus(&view->navigation_view,
                                              (scooter_page_id_t)view->sidebar_focus_index);
}

/* 主题切换先落到 view 层，业务层不直接依赖设置页内部状态。 */
static void scooter_shell_view_apply_theme(scooter_shell_view_t *view, int theme_index)
{
    if (!view)
        return;

    if (theme_index < 0 || theme_index >= 3)
        theme_index = 0;

    view->theme_index = (uint8_t)theme_index;
    scooter_main_view_set_theme(&view->main_view, theme_index);
    scooter_navigation_view_set_theme(&view->navigation_view, theme_index);
    scooter_music_view_set_theme(&view->music_view, theme_index);
    scooter_settings_view_set_active_theme(&view->settings_view, theme_index);
}

/* 低电量提醒是 AI 演示态，离开 AI 后由 shell 在跨页面操作时恢复主页默认电量显示。 */
static void scooter_shell_view_clear_low_battery_demo(scooter_shell_view_t *view)
{
    if (!view || !view->main_view.low_battery_reminder)
        return;

    scooter_main_view_set_low_battery_reminder(&view->main_view, false);
}

static void scooter_shell_view_request_nav_work(scooter_shell_view_t *view,
                                                scooter_shell_nav_work_action_t action)
{
    rt_thread_t thread;
    rt_base_t level;
    bool worker_running;

    if (!view || action == SCOOTER_SHELL_NAV_WORK_NONE)
        return;

    level = rt_hw_interrupt_disable();
    view->nav_worker_action = (uint8_t)action;
    view->nav_worker_seq++;
    worker_running = view->nav_worker_running;
    if (!worker_running)
        view->nav_worker_running = true;
    rt_hw_interrupt_enable(level);

    if (worker_running)
        return;

    thread = rt_thread_create("navwork",
                              scooter_shell_view_nav_worker_entry,
                              view,
                              SCOOTER_SHELL_NAV_WORKER_STACK,
                              SCOOTER_SHELL_NAV_WORKER_PRIORITY,
                              20);
    if (thread) {
        rt_thread_startup(thread);
    } else {
        level = rt_hw_interrupt_disable();
        view->nav_worker_running = false;
        view->nav_worker_busy = false;
        rt_hw_interrupt_enable(level);
        SCOOTER_SHELL_LOG("failed to create navigation worker");
    }
}

static void scooter_shell_view_nav_worker_entry(void *parameter)
{
    scooter_shell_view_t *view = parameter;

    if (!view)
        return;

    for (;;) {
        uint32_t seq;
        uint8_t action;
        rt_base_t level;

        level = rt_hw_interrupt_disable();
        if (view->nav_worker_handled_seq == view->nav_worker_seq) {
            view->nav_worker_busy = false;
            view->nav_worker_running = false;
            rt_hw_interrupt_enable(level);
            return;
        }
        view->nav_worker_busy = true;
        seq = view->nav_worker_seq;
        action = view->nav_worker_action;
        view->nav_worker_handled_seq = seq;
        rt_hw_interrupt_enable(level);

        switch ((scooter_shell_nav_work_action_t)action) {
        case SCOOTER_SHELL_NAV_WORK_START_DISPLAY:
            if (rvt_map_show_location() < 0)
                SCOOTER_SHELL_LOG("navigation display start failed");
            break;
        case SCOOTER_SHELL_NAV_WORK_STOP:
            rvt_wifi_display_stop();
            break;
        default:
            break;
        }
    }
}

