/* 把蓝牙歌曲名和歌手名同步到主页音乐卡片。 */
static void scooter_main_view_apply_audio_info(scooter_main_view_t *view,
                                               const rvt_audio_info_t *info)
{
    rvt_audio_info_t previous;
    const char *title = SCOOTER_MUSIC_TITLE_TEXT;
    const char *artist = SCOOTER_MUSIC_ARTIST_TEXT;
    bool keep_previous_track = false;

    if (!view || !info)
        return;

    previous = view->audio_info;
    if ((info->ready || info->connected) &&
        info->connected &&
        info->title[0] == '\0' &&
        previous.title[0] != '\0') {
        keep_previous_track = true;
    }

    view->audio_info = *info;
    if (keep_previous_track) {
        strncpy(view->audio_info.title, previous.title, sizeof(view->audio_info.title) - 1U);
        view->audio_info.title[sizeof(view->audio_info.title) - 1U] = '\0';
        strncpy(view->audio_info.artist, previous.artist, sizeof(view->audio_info.artist) - 1U);
        view->audio_info.artist[sizeof(view->audio_info.artist) - 1U] = '\0';
    }

    if (keep_previous_track)
        title = view->audio_info.title;
    else if (info->title[0] != '\0')
        title = info->title;

    if (keep_previous_track && view->audio_info.artist[0] != '\0')
        artist = view->audio_info.artist;
    else if (info->artist[0] != '\0')
        artist = info->artist;
    else if (info->device_name[0] != '\0')
        artist = info->device_name;
    else if (info->connected)
        artist = "蓝牙已连接";

    scooter_set_label_text(view->music_title_value, title);
    scooter_set_label_text(view->music_artist_value, artist);
    scooter_main_view_update_album_rotation(view);
}

