/* 统一切页入口，同时刷新当前页 on_show 逻辑和可见焦点。 */
static void scooter_shell_view_switch_page(scooter_shell_view_t *view, scooter_page_id_t page_id)
{
    scooter_page_id_t old_page;
    bool nav_enter_external;

    if (!view || page_id >= SCOOTER_PAGE_COUNT)
        return;

    old_page = view->page_manager.active_page;
    nav_enter_external = view->nav_enter_external;
    view->nav_enter_external = false;

    if (page_id == SCOOTER_PAGE_NAVIGATION &&
        old_page != SCOOTER_PAGE_NAVIGATION &&
        !view->nav_restore_valid) {
        view->nav_restore_page = old_page;
        view->nav_restore_valid = true;
    }

    SCOOTER_SHELL_LOG("switch page %u -> %u view=%p prev=%u",
                      (unsigned int)view->page_manager.active_page,
                      (unsigned int)page_id,
                      (void *)view,
                      (unsigned int)view->page_manager.previous_page);

    if (old_page == SCOOTER_PAGE_NAVIGATION && old_page != page_id) {
        scooter_cast_ui_layer_manager_exit_projection(&view->cast_ui_layer_manager);
        scooter_navigation_view_hide(&view->navigation_view);
        scooter_shell_view_request_nav_work(view, SCOOTER_SHELL_NAV_WORK_STOP);
        view->nav_restore_valid = false;
        view->nav_restore_page = SCOOTER_PAGE_HOME;
    }

    if (old_page == SCOOTER_PAGE_HOME && old_page != page_id)
        scooter_main_view_hide(&view->main_view);

    if (old_page == SCOOTER_PAGE_MUSIC && old_page != page_id)
        scooter_music_view_hide(&view->music_view);

    if (old_page == SCOOTER_PAGE_SETTINGS && old_page != page_id)
        scooter_settings_view_hide(&view->settings_view);

    scooter_page_manager_show(&view->page_manager, page_id);

    if (page_id == SCOOTER_PAGE_HOME || page_id == SCOOTER_PAGE_NAVIGATION) {
        view->sidebar_focus_index = (uint8_t)page_id;
        scooter_shell_view_apply_sidebar_focus(view);
    }

    switch (page_id) {
    case SCOOTER_PAGE_HOME:
        scooter_main_view_show(&view->main_view);
        break;
    case SCOOTER_PAGE_NAVIGATION:
        if (view->main_view.has_state)
            scooter_navigation_view_set_speed(&view->navigation_view,
                                              view->main_view.last_state.speed_kmh);
        if (nav_enter_external)
            scooter_navigation_view_show_external(&view->navigation_view);
        else
            scooter_navigation_view_show(&view->navigation_view);
        if (!nav_enter_external)
            scooter_shell_view_request_nav_work(view,
                                                SCOOTER_SHELL_NAV_WORK_START_DISPLAY);
        break;
    case SCOOTER_PAGE_MUSIC:
        SCOOTER_SHELL_LOG("enter music page music_view=%p screen=%p",
                          (void *)&view->music_view,
                          (void *)view->music_view.screen);
        scooter_music_view_show(&view->music_view);
        break;
    case SCOOTER_PAGE_SETTINGS:
        scooter_settings_view_show(&view->settings_view);
        break;
    default:
        break;
    }
}

static void scooter_shell_view_enter_navigation_page(scooter_shell_view_t *view,
                                                     scooter_page_id_t restore_page)
{
    if (!view)
        return;

    if (restore_page >= SCOOTER_PAGE_COUNT)
        restore_page = view->page_manager.active_page;
    if (restore_page == SCOOTER_PAGE_NAVIGATION)
        restore_page = SCOOTER_PAGE_HOME;

    if (!view->nav_restore_valid) {
        view->nav_restore_page = restore_page;
        view->nav_restore_valid = true;
    }

    view->nav_enter_external = true;
    scooter_shell_view_switch_page(view, SCOOTER_PAGE_NAVIGATION);
}

static void scooter_shell_view_exit_navigation_page(scooter_shell_view_t *view)
{
    scooter_page_id_t restore_page;

    if (!view)
        return;

    restore_page = view->nav_restore_valid ?
        view->nav_restore_page : SCOOTER_PAGE_HOME;

    if (restore_page >= SCOOTER_PAGE_COUNT ||
        restore_page == SCOOTER_PAGE_NAVIGATION) {
        restore_page = SCOOTER_PAGE_HOME;
    }

    view->nav_restore_valid = false;
    view->nav_restore_page = SCOOTER_PAGE_HOME;
    scooter_shell_view_switch_page(view, restore_page);
}

/* 返回键优先交给设置页内部消费，剩余情况统一按 previous_page 退回。 */
static void scooter_shell_view_go_back(scooter_shell_view_t *view)
{
    scooter_page_id_t previous_page;

    if (!view)
        return;

    if (view->page_manager.active_page == SCOOTER_PAGE_SETTINGS &&
        scooter_settings_view_handle_back(&view->settings_view)) {
        return;
    }

    if (view->page_manager.active_page == SCOOTER_PAGE_HOME)
        return;

    previous_page = view->page_manager.previous_page;
    if (previous_page >= SCOOTER_PAGE_COUNT ||

#if defined(RIVOTEK_APP_SCOOTER_UI_AI_CHAT)
        if (view->ai_session_active && view->ai_restore_page < SCOOTER_PAGE_COUNT)
            scooter_shell_view_enter_navigation_page(view, view->ai_restore_page);
        else
#endif
        scooter_shell_view_enter_navigation_page(view, view->page_manager.active_page);
    }

    switch (map_event.type) {
    case RVT_MAP_UI_NAV_LOADING:
        scooter_navigation_view_set_loading(&view->navigation_view);
        scooter_cast_ui_layer_manager_enter_projection(&view->cast_ui_layer_manager);
        break;
    case RVT_MAP_UI_NAV_ACTIVE:
        scooter_navigation_view_set_active(&view->navigation_view);
        scooter_cast_ui_layer_manager_enter_projection(&view->cast_ui_layer_manager);
        break;
    case RVT_MAP_UI_NAV_FAILED:
        scooter_cast_ui_layer_manager_exit_projection(&view->cast_ui_layer_manager);
        scooter_navigation_view_set_failed(&view->navigation_view);
        break;
    default:
        break;
    }
}

void scooter_shell_view_init(scooter_shell_view_t *view,
                             rvt_event_bus_t *event_bus,
                             const scooter_state_t *initial_state)
{
    lv_obj_t *page_root;

    if (!view)
        return;

    memset(view, 0, sizeof(*view));
    view->event_bus = event_bus;
    view->model_changed_handle = -1;
    view->map_ui_handle = -1;
    view->disp_w = SCOOTER_DEMO_SCREEN_WIDTH;
    view->disp_h = SCOOTER_DEMO_SCREEN_HEIGHT;
    view->sidebar_focus_index = SCOOTER_PAGE_HOME;
    view->theme_index = 0;
    view->nav_restore_page = SCOOTER_PAGE_HOME;
    view->nav_restore_valid = false;
    view->nav_enter_external = false;

    view->screen = lv_obj_create(NULL);
    lv_obj_remove_style_all(view->screen);
    lv_obj_clear_flag(view->screen, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(view->screen, view->disp_w, view->disp_h);
    lv_obj_set_style_bg_color(view->screen, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(view->screen, LV_OPA_COVER, 0);
    lv_obj_add_event_cb(view->screen, scooter_shell_view_screen_event_cb,
                        LV_EVENT_DELETE, view);

    scooter_page_manager_init(&view->page_manager);

    page_root = scooter_page_manager_create_container(view->screen, view->disp_w, view->disp_h);
    scooter_page_manager_register(&view->page_manager, SCOOTER_PAGE_HOME, page_root);
    scooter_main_view_build(&view->main_view, page_root, event_bus, initial_state);

    page_root = scooter_page_manager_create_container(view->screen, view->disp_w, view->disp_h);
    scooter_page_manager_register(&view->page_manager, SCOOTER_PAGE_NAVIGATION, page_root);
    scooter_navigation_view_build(&view->navigation_view, page_root);
    scooter_cast_ui_layer_manager_init(&view->cast_ui_layer_manager);
    scooter_cast_ui_layer_manager_set_targets(&view->cast_ui_layer_manager,
                                              view->navigation_view.status_bar,
                                              view->navigation_view.sidebar_panel,
                                              view->navigation_view.sidebar);
    if (initial_state)
        scooter_navigation_view_set_speed(&view->navigation_view,
                                          initial_state->speed_kmh);

    if (event_bus) {
        view->model_changed_handle = rvt_event_bus_subscribe(event_bus,
                                                             SCOOTER_EVENT_MODEL_CHANGED,
                                                             scooter_shell_view_model_changed_cb,
                                                             view);
        view->map_ui_handle = rvt_event_bus_subscribe(event_bus,
                                                      RVT_MAP_EVENT_UI,
                                                      scooter_shell_view_map_ui_cb,
                                                      view);
        rvt_map_set_event_bus(event_bus);
    }

    page_root = scooter_page_manager_create_container(view->screen, view->disp_w, view->disp_h);
    scooter_page_manager_register(&view->page_manager, SCOOTER_PAGE_MUSIC, page_root);
    scooter_music_view_build(&view->music_view, page_root);

    page_root = scooter_page_manager_create_container(view->screen, view->disp_w, view->disp_h);
    scooter_page_manager_register(&view->page_manager, SCOOTER_PAGE_SETTINGS, page_root);
    scooter_settings_view_build(&view->settings_view, page_root);
    scooter_settings_view_set_theme_apply_cb(&view->settings_view,
                                             scooter_shell_view_settings_theme_apply,
                                             view);

#if defined(RIVOTEK_APP_SCOOTER_UI_AI_CHAT)
    ai_chat_view_init(&view->ai_chat_view, view->screen, event_bus);
    ai_chat_view_set_low_battery_cb(&view->ai_chat_view,
                                    scooter_shell_view_low_battery_cb,
                                    view);
    view->ai_restore_page = SCOOTER_PAGE_HOME;
    view->ai_session_active = false;
#endif

    view->theme_index = (uint8_t)scooter_settings_view_get_active_theme();
    scooter_shell_view_apply_theme(view, view->theme_index);
    scooter_shell_view_apply_sidebar_focus(view);
    scooter_shell_view_switch_page(view, SCOOTER_PAGE_HOME);

    view->input_timer = lv_timer_create(scooter_shell_view_input_timer_cb,
                                        SCOOTER_SHELL_INPUT_POLL_MS,
                                        view);

    g_active_shell_view = view;
}

void scooter_shell_view_show(scooter_shell_view_t *view)
{
    if (!view || !view->screen)
        return;

    g_active_shell_view = view;
    scooter_shell_view_switch_page(view, view->page_manager.active_page);
    lv_scr_load(view->screen);
}

void scooter_shell_view_set_main_controller(scooter_shell_view_t *view,
                                            scooter_main_controller_t *controller)
{
    if (!view)
        return;

    view->main_controller = controller;
}

scooter_main_view_t *scooter_shell_view_get_main_view(scooter_shell_view_t *view)
{
    if (!view)
        return NULL;

    return &view->main_view;
}

