static void scooter_main_view_apply_battery_display(scooter_main_view_t *view,
                                                    uint8_t percent)
{
    char power_text[24];
    char battery_text[8];
    uint8_t display_percent;

    if (!view)
        return;

    display_percent = view->low_battery_reminder ? 30U : percent;
    lv_snprintf(power_text, sizeof(power_text), "%u%%", display_percent);
    scooter_set_label_text(view->power_value, power_text);
    lv_snprintf(battery_text, sizeof(battery_text), "%u%%", display_percent);
    scooter_set_label_text(view->battery_value, battery_text);

    if (view->low_battery_reminder) {
        uint8_t theme_index = view->theme_index;

        if (theme_index >= 3)
            theme_index = SCOOTER_DEFAULT_THEME_IDX;
        scooter_set_image(view->bottom_theme_img, g_bottom_low_battery_assets[theme_index]);
        if (view->bottom_theme_cont) {
            lv_obj_set_size(view->bottom_theme_cont,
                            scooter_scale_w(view, 360),
                            scooter_scale_h(view, 20));
            lv_obj_align(view->bottom_theme_cont,
                         LV_ALIGN_BOTTOM_MID,
                         0,
                         scooter_scale_h(view, SCOOTER_BOTTOM_THEME_BASE_BOTTOM_Y));
        }
        if (view->bottom_theme_img) {
            lv_obj_set_size(view->bottom_theme_img,
                            scooter_scale_w(view, 360),
                            scooter_scale_h(view, 20));
            lv_obj_align(view->bottom_theme_img, LV_ALIGN_CENTER, 0, 0);
        }
    }
}

static void scooter_main_view_sync_clock(scooter_main_view_t *view)
{
    char time_text[8];
    bool time_ready;

    if (!view)
        return;

    time_ready = rvt_time_service_is_ready();
    scooter_get_time_text(time_text, sizeof(time_text));

    scooter_set_label_text(view->time_value, time_text);
    scooter_set_label_text(view->location_value,
                           time_ready ? rvt_weather_service_get_city_text() : "--");
}

static void scooter_main_view_fit_weather_desc(scooter_main_view_t *view)
{
    lv_obj_t *parent;
    lv_coord_t right;
    lv_coord_t max_right;

    if (!view || !view->weather_desc_value || !view->left_temp_value)
        return;

    lv_obj_align_to(view->weather_desc_value,
                    view->left_temp_value,
                    LV_ALIGN_OUT_RIGHT_MID,
                    scooter_scale_w(view, 35),
                    0);
    lv_obj_update_layout(view->weather_desc_value);

    parent = lv_obj_get_parent(view->weather_desc_value);
    if (!parent)
        return;

    right = lv_obj_get_x(view->weather_desc_value) +
            lv_obj_get_width(view->weather_desc_value);
    max_right = lv_obj_get_width(parent) - scooter_scale_w(view, 4);
    if (right > max_right) {
        lv_obj_set_x(view->weather_desc_value,
                     lv_obj_get_x(view->weather_desc_value) - (right - max_right));
    }
}

static void scooter_main_view_sync_weather(scooter_main_view_t *view)
{
    const char *weather_icon_path;
    const char *temp_text;
    const char *weather_text;

    if (!view)
        return;

    weather_icon_path = rvt_weather_icon_path(rvt_weather_service_get_icon_type());
    temp_text = rvt_weather_service_get_temp_text();
    weather_text = rvt_weather_service_get_desc_text();
    if (view->sun_icon) {
        const void *current_src = lv_img_get_src(view->sun_icon);

        if (!current_src || strcmp((const char *)current_src, weather_icon_path) != 0)
            lv_img_set_src(view->sun_icon, weather_icon_path);
    }
    scooter_set_label_text(view->temp_value, temp_text);
    scooter_set_label_text(view->left_temp_value, temp_text);
    scooter_set_label_text(view->weather_desc_value, weather_text);
    scooter_main_view_fit_weather_desc(view);
    scooter_set_label_text(view->weather_air_value,
                           rvt_weather_service_get_air_quality_text());
}

static void scooter_main_view_set_center_meter_visible(scooter_main_view_t *view, bool visible)
{
    bool show_standby_speed_bg;
    bool show_driving_speed_bg;

    if (!view)
        return;

    show_standby_speed_bg = visible &&
                            !view->last_state.driver_demo_running &&
                            !view->idle_media_visible;
    show_driving_speed_bg = visible &&
                            view->last_state.driver_demo_running &&
                            !view->idle_media_visible;

    if (view->speed_bg_img) {
        if (show_standby_speed_bg)
            lv_obj_clear_flag(view->speed_bg_img, LV_OBJ_FLAG_HIDDEN);
        else
            lv_obj_add_flag(view->speed_bg_img, LV_OBJ_FLAG_HIDDEN);
    }

    if (view->driving_speed_bg_img) {
        if (show_driving_speed_bg)
            lv_obj_clear_flag(view->driving_speed_bg_img, LV_OBJ_FLAG_HIDDEN);
        else
            lv_obj_add_flag(view->driving_speed_bg_img, LV_OBJ_FLAG_HIDDEN);
    }

    if (view->speed_unit_value) {
        if (visible && !view->idle_media_visible)
            lv_obj_clear_flag(view->speed_unit_value, LV_OBJ_FLAG_HIDDEN);
        else
            lv_obj_add_flag(view->speed_unit_value, LV_OBJ_FLAG_HIDDEN);
    }

    if (view->speed_value) {
        if (visible && !view->idle_media_visible)
            lv_obj_clear_flag(view->speed_value, LV_OBJ_FLAG_HIDDEN);
        else
            lv_obj_add_flag(view->speed_value, LV_OBJ_FLAG_HIDDEN);
    }
}

static void scooter_main_view_hide_center_media(scooter_main_view_t *view)
{
    if (!view)
        return;

    if (view->home_gif_slot)
        lv_obj_add_flag(view->home_gif_slot, LV_OBJ_FLAG_HIDDEN);
    scooter_main_view_delete_home_gif(view);
    if (view->home_effect_label)
        lv_obj_add_flag(view->home_effect_label, LV_OBJ_FLAG_HIDDEN);
}

static void scooter_main_view_restore_center_meter(scooter_main_view_t *view)
{
    if (!view)
        return;

    view->idle_media_visible = false;
    scooter_main_view_hide_center_media(view);
    scooter_main_view_set_center_meter_visible(view, true);
}

static void scooter_main_view_update_driver_demo_effect(scooter_main_view_t *view,
                                                        scooter_driver_demo_effect_t effect)
{
    const char *gif_path = NULL;
    const char *fallback_text = NULL;

    if (!view)
        return;

    if (effect == view->current_demo_effect)
        return;

    view->current_demo_effect = effect;

    if (effect == SCOOTER_DRIVER_DEMO_EFFECT_NONE) {
        if (!view->idle_media_visible)
            scooter_main_view_hide_center_media(view);
        return;
    }

    if (!view->home_gif_slot)
        return;

    if ((unsigned int)effect <
        (sizeof(g_home_driver_effect_gif_assets) / sizeof(g_home_driver_effect_gif_assets[0]))) {
        gif_path = g_home_driver_effect_gif_assets[(unsigned int)effect];
    }
    fallback_text = (effect == SCOOTER_DRIVER_DEMO_EFFECT_ACCEL) ? "急加速" : "急刹车";

    view->idle_media_visible = false;
    lv_obj_align(view->home_gif_slot, LV_ALIGN_CENTER, 0, scooter_scale_h(view, -10));
    scooter_main_view_show_center_media(view, gif_path, fallback_text);
    scooter_main_view_set_center_meter_visible(view, true);
    if (view->speed_value)
        lv_obj_move_foreground(view->speed_value);
    if (view->speed_unit_value)
        lv_obj_move_foreground(view->speed_unit_value);
}

static void scooter_main_view_show_center_media(scooter_main_view_t *view,
                                                const char *gif_path,
                                                const char *fallback_text)
{
    lv_obj_t *gif_img = NULL;

    if (!view || !view->home_gif_slot)
        return;

    lv_obj_clear_flag(view->home_gif_slot, LV_OBJ_FLAG_HIDDEN);

    if (gif_path) {
        gif_img = scooter_main_view_ensure_home_gif(view);
        if (gif_img) {
            lv_gif_set_src(gif_img, gif_path);
            if (scooter_main_view_home_gif_loaded(gif_img)) {
                lv_obj_center(gif_img);
                lv_obj_clear_flag(gif_img, LV_OBJ_FLAG_HIDDEN);
}

/* 创建一个透明的可点击热区。 */
static lv_obj_t *scooter_create_touch_area(lv_obj_t *parent, lv_coord_t width, lv_coord_t height)
{
    lv_obj_t *touch = lv_obj_create(parent);

    lv_obj_remove_style_all(touch);
    lv_obj_set_size(touch, width, height);
    lv_obj_add_flag(touch, LV_OBJ_FLAG_CLICKABLE | LV_OBJ_FLAG_IGNORE_LAYOUT);
    lv_obj_set_style_bg_opa(touch, LV_OPA_0, 0);
    lv_obj_set_style_border_width(touch, 0, 0);
    lv_obj_clear_flag(touch, LV_OBJ_FLAG_SCROLLABLE);
    return touch;
}

/* 创建一个无背景无边框的透明容器。 */
static lv_obj_t *scooter_create_transparent_container(lv_obj_t *parent, lv_coord_t width, lv_coord_t height)
{
    lv_obj_t *cont = lv_obj_create(parent);

    lv_obj_remove_style_all(cont);
    lv_obj_set_size(cont, width, height);
    lv_obj_set_style_bg_opa(cont, LV_OPA_0, 0);
    lv_obj_set_style_border_width(cont, 0, 0);
    lv_obj_clear_flag(cont, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_scrollbar_mode(cont, LV_SCROLLBAR_MODE_OFF);
    return cont;
}

