/* 主页/导航页共用侧边栏键位逻辑。 */
static void scooter_shell_view_handle_sidebar_event(scooter_shell_view_t *view,
                                                    rvt_input_key_t key,
                                                    rvt_input_event_t event)
{
    if (!view)
        return;

    if (key == RVT_INPUT_KEY_UP &&
        event == RVT_INPUT_EVENT_DOUBLE_CLICK &&
        view->page_manager.active_page == SCOOTER_PAGE_HOME) {
        scooter_main_controller_start_drive_demo(view->main_controller);
        return;
    }

    if (key == RVT_INPUT_KEY_DOWN &&
        event == RVT_INPUT_EVENT_DOUBLE_CLICK &&
        view->page_manager.active_page == SCOOTER_PAGE_HOME) {
        scooter_main_controller_stop_drive_demo(view->main_controller);
        return;
    }

    if (key == RVT_INPUT_KEY_OK &&
        event == RVT_INPUT_EVENT_DOUBLE_CLICK &&
        view->page_manager.active_page == SCOOTER_PAGE_NAVIGATION) {
        scooter_shell_view_exit_navigation_page(view);
        return;
    }

    if (event != RVT_INPUT_EVENT_SHORT_PRESS)
        return;

    switch (key) {
    case RVT_INPUT_KEY_UP:
        view->sidebar_focus_index = (uint8_t)((view->sidebar_focus_index + SCOOTER_PAGE_COUNT - 1U) %
                                              SCOOTER_PAGE_COUNT);
        scooter_shell_view_apply_sidebar_focus(view);
        break;
    case RVT_INPUT_KEY_DOWN:
        view->sidebar_focus_index = (uint8_t)((view->sidebar_focus_index + 1U) %
                                              SCOOTER_PAGE_COUNT);
        scooter_shell_view_apply_sidebar_focus(view);
        break;
    case RVT_INPUT_KEY_OK:
        scooter_shell_view_switch_page(view,
                                       (scooter_page_id_t)view->sidebar_focus_index);
        break;
    default:
        break;
    }
}

/* 音乐页按键统一映射到上一曲、下一曲和播放控制。 */
static void scooter_shell_view_handle_music_event(scooter_shell_view_t *view,
                                                  rvt_input_key_t key,
                                                  rvt_input_event_t event)
{
