/* 构建主页对象树，既支持独立 screen，也支持挂进页面管理器容器。 */
void scooter_main_view_build(scooter_main_view_t *view, lv_obj_t *parent,
                             rvt_event_bus_t *event_bus,
                             const scooter_state_t *initial_state)
{
    if (!view)
        return;

    memset(view, 0, sizeof(*view));
    view->event_bus = event_bus;
    view->model_changed_handle = -1;
    view->audio_changed_handle = -1;
    view->disp_w = SCOOTER_DEMO_SCREEN_WIDTH;
    view->disp_h = SCOOTER_DEMO_SCREEN_HEIGHT;
    view->theme_index = SCOOTER_DEFAULT_THEME_IDX;
    view->sidebar_focus_index = SCOOTER_PAGE_HOME;
    view->owns_screen = (parent == NULL);
    scooter_main_view_create_fonts(view);

    view->screen = lv_obj_create(parent);
    lv_obj_remove_style_all(view->screen);
    lv_obj_clear_flag(view->screen, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(view->screen, view->disp_w, view->disp_h);
    lv_obj_set_style_bg_color(view->screen, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(view->screen, LV_OPA_COVER, 0);
    lv_obj_align(view->screen, LV_ALIGN_CENTER, 0, 0);
    lv_obj_add_event_cb(view->screen, scooter_screen_event_cb, LV_EVENT_DELETE, view);

    scooter_create_home_background_layers(view);
    scooter_create_music_panel(view);
    scooter_create_meter(view);
    scooter_create_info_panel(view);
    scooter_create_bottom_panel(view);
    scooter_create_status_bar(view);
    scooter_create_sidebar(view);
    view->last_idle_switch_tick = lv_tick_get();
    view->last_home_activity_tick = view->last_idle_switch_tick;
    view->last_slow_sync_tick = view->last_idle_switch_tick;
    view->last_audio_sync_tick = view->last_idle_switch_tick;
    srand((unsigned int)time(NULL) ^ (unsigned int)view->last_idle_switch_tick);

    if (event_bus) {
        view->model_changed_handle = rvt_event_bus_subscribe(event_bus,
                                                                 SCOOTER_EVENT_MODEL_CHANGED,
                                                                 scooter_model_changed_cb,
                                                                 view);
    }
    scooter_main_view_sync_audio_once(view);

    view->ui_timer = lv_timer_create(scooter_ui_timer_cb, SCOOTER_UI_FAST_TIMER_MS, view);
    if (view->ui_timer)
        lv_timer_pause(view->ui_timer);

    if (initial_state)
        scooter_main_view_apply_state(view, initial_state);
}

/* 兼容旧入口，默认按独立 screen 方式构建主页。 */
void scooter_main_view_init(scooter_main_view_t *view, rvt_event_bus_t *event_bus,
                            const scooter_state_t *initial_state)
{
    scooter_main_view_build(view, NULL, event_bus, initial_state);
}

/* 仅在主页独占 screen 时直接切屏；挂到 page manager 下由上层统一 show/hide。 */
void scooter_main_view_show(scooter_main_view_t *view)
{
    if (!view || !view->screen)
        return;

    view->visible = true;
    view->last_home_activity_tick = lv_tick_get();
    view->last_audio_sync_tick = view->last_home_activity_tick;
    view->idle_media_visible = false;
    scooter_main_view_hide_center_media(view);
    scooter_main_view_set_audio_subscription(view, true);
    if (view->owns_screen)
        lv_scr_load(view->screen);

    if (view->has_state)
        scooter_main_view_apply_state(view, &view->last_state);
    scooter_main_view_sync_audio_once(view);
    if (view->ui_timer) {
        lv_timer_resume(view->ui_timer);
        lv_timer_ready(view->ui_timer);
    }
}

void scooter_main_view_hide(scooter_main_view_t *view)
{
    if (!view)
        return;

    view->visible = false;
    view->idle_media_visible = false;
    scooter_main_view_hide_center_media(view);
    scooter_main_view_set_audio_subscription(view, false);
    if (view->ui_timer)
        lv_timer_pause(view->ui_timer);
}

