/* 设置首页中心区域的待机动画资源。 */
static void scooter_main_view_set_idle_gif(scooter_main_view_t *view, uint8_t gif_index)
{
    lv_obj_t *gif_img;

    if (!view)
        return;

    gif_img = scooter_main_view_ensure_home_gif(view);
    if (!gif_img)
        return;

    gif_index = (uint8_t)(gif_index % SCOOTER_HOME_GIF_COUNT);
    view->idle_gif_index = gif_index;
    lv_gif_set_src(gif_img, g_home_idle_gif_assets[gif_index]);
    if (!scooter_main_view_home_gif_loaded(gif_img))
        return;
    lv_obj_align(view->home_gif_slot, LV_ALIGN_CENTER, 0, scooter_scale_h(view, -10));
    lv_obj_clear_flag(view->home_gif_slot, LV_OBJ_FLAG_HIDDEN);
    lv_obj_center(gif_img);
    lv_obj_clear_flag(gif_img, LV_OBJ_FLAG_HIDDEN);
    if (view->home_effect_label)
        lv_obj_add_flag(view->home_effect_label, LV_OBJ_FLAG_HIDDEN);
    view->idle_media_visible = true;
    scooter_main_view_set_center_meter_visible(view, false);
}

