static void draw_buf_to_region(
    const lv_draw_buf_t * draw_buf, const lv_area_t * area,
    lv_uintptr_t * start, lv_uintptr_t * end)
{
    LV_ASSERT_NULL(draw_buf);
    LV_ASSERT_NULL(area);
    LV_ASSERT_NULL(start);
    LV_ASSERT_NULL(end);

    uint32_t palette_size_bytes = 0;
    /** Jump pattern color table */
    if(LV_COLOR_FORMAT_IS_INDEXED(draw_buf->header.cf)) {
        palette_size_bytes = LV_COLOR_INDEXED_PALETTE_SIZE(draw_buf->header.cf) * sizeof(lv_color32_t);
    }

    void * buf = draw_buf->data + palette_size_bytes;
    uint32_t stride = draw_buf->header.stride;
    int32_t h = lv_area_get_height(area);
    *start = (lv_uintptr_t)buf + area->y1 * stride;
    *end = *start + h * stride;
}

static void draw_buf_pattern_region(const lv_draw_buf_t * draw_buf, lv_uintptr_t * start, lv_uintptr_t * end)
{
    LV_ASSERT_NULL(draw_buf);
    LV_ASSERT_NULL(start);
    LV_ASSERT_NULL(end);

    uint32_t palette_size_bytes = LV_COLOR_INDEXED_PALETTE_SIZE(draw_buf->header.cf) * sizeof(lv_color32_t);
    void * buf = draw_buf->data;
    *start = (lv_uintptr_t)buf;
    *end = *start + palette_size_bytes;
}

static void invalidate_cache(const lv_draw_buf_t * draw_buf, const lv_area_t * area)
{
    lv_uintptr_t start;
    lv_uintptr_t end;
    draw_buf_to_region(draw_buf, area, &start, &end);
    up_invalidate_dcache(start, end);

    /** Need to invalidate the pattern color table */
    if(LV_COLOR_FORMAT_IS_INDEXED(draw_buf->header.cf)) {
        draw_buf_pattern_region(draw_buf, &start, &end);
        up_invalidate_dcache(start, end);
    }
}

static void flush_cache(const lv_draw_buf_t * draw_buf, const lv_area_t * area)
{
    lv_uintptr_t start;
    lv_uintptr_t end;
    draw_buf_to_region(draw_buf, area, &start, &end);
    up_flush_dcache(start, end);

    /** Need to flush the pattern color table */
    if(LV_COLOR_FORMAT_IS_INDEXED(draw_buf->header.cf)) {
        draw_buf_pattern_region(draw_buf, &start, &end);
        up_flush_dcache(start, end);
    }
}

