static void ai_chat_fade(lv_obj_t *obj, lv_opa_t from, lv_opa_t to)
{
    lv_anim_t anim;

    if (!obj)
        return;

    lv_anim_delete(obj, ai_chat_set_opa_anim);
    lv_obj_set_style_opa(obj, from, 0);
    lv_obj_clear_flag(obj, LV_OBJ_FLAG_HIDDEN);

    lv_anim_init(&anim);
    lv_anim_set_var(&anim, obj);
    lv_anim_set_values(&anim, from, to);
    lv_anim_set_time(&anim, AI_CHAT_FADE_MS);
    lv_anim_set_exec_cb(&anim, ai_chat_set_opa_anim);
    lv_anim_set_path_cb(&anim, lv_anim_path_ease_in_out);
    if (to == LV_OPA_0) {
        lv_anim_set_user_data(&anim, obj);
        lv_anim_set_completed_cb(&anim, ai_chat_fade_done_cb);
    }
    lv_anim_start(&anim);
}

