static uint8_t aicfb_nuttx_fb_format(uint32_t mpp_format, uint32_t bpp) {
  switch (mpp_format) {
  case MPP_FMT_RGB_888:
  case MPP_FMT_BGR_888:
    return FB_FMT_RGB24;

  case MPP_FMT_RGB_565:
  case MPP_FMT_BGR_565:
    return FB_FMT_RGB16_565;

  case MPP_FMT_XRGB_8888:
  case MPP_FMT_XBGR_8888:
  case MPP_FMT_RGBX_8888:
  case MPP_FMT_BGRX_8888:
    return FB_FMT_RGB32;

  case MPP_FMT_ARGB_8888:
  case MPP_FMT_ABGR_8888:
  case MPP_FMT_RGBA_8888:
  case MPP_FMT_BGRA_8888:
    return FB_FMT_RGBA32;

  default:
    break;
  }

  switch (bpp) {
  case 16:
    return FB_FMT_RGB16_565;
  case 24:
    return FB_FMT_RGB24;
  case 32:
    return FB_FMT_RGB32;
  default:
    return FB_FMT_RGBRAW;
  }
}

static int aicfb_pandisplay(struct fb_vtable_s *vtable,
                            struct fb_planeinfo_s *pinfo) {
  struct aicfb_info *fbi = aicfb_get_drvdata();
  int ret;

  if (!vtable || !pinfo || !fbi)
    return -EINVAL;

  ret = aicfb_pan_display(fbi, pinfo->yoffset / fbi->height);
  if (ret == 0) {
    fb_remove_paninfo(vtable, FB_NO_OVERLAY);
  }

  return ret;
}

