    struct dfs_filesystem *fs = dfs_filesystem_lookup(LVGL_STORAGE_PATH);

    if (!fs || strncmp(LVGL_STORAGE_PATH, fs->path, 3) != 0)
        return false;
#endif

    if (access(SCOOTER_STORAGE_PROBE_PATH, R_OK) == 0) {
        if (!g_storage_probe_ready_logged) {
            printf("scooter_demo: resource ready: %s\n",
                   SCOOTER_STORAGE_PROBE_PATH);
            g_storage_probe_ready_logged = true;
        }
        g_storage_probe_error_logged = false;
        return true;
    }

    g_storage_probe_ready_logged = false;
    if (!g_storage_probe_error_logged) {
        printf("scooter_demo: resource unavailable: %s (errno=%d)\n",
               SCOOTER_STORAGE_PROBE_PATH, errno);
        g_storage_probe_error_logged = true;
    }
    return false;
}

/* 文件系统就绪后再切换到主页面，避免首页资源加载失败。 */
static void scooter_app_storage_poll_timer_cb(lv_timer_t *timer)
{
    scooter_app_ctx_t *app = timer ? timer->user_data : NULL;

    if (!app || !scooter_app_storage_ready())
        return;

    printf("scooter_demo: resource poll ready, boot_finished=%d\n",
           app->boot_anim_finished ? 1 : 0);
    if (app->storage_poll_timer) {
        lv_timer_del(app->storage_poll_timer);
        app->storage_poll_timer = NULL;
    }

    if (app->boot_anim_finished)
        scooter_app_show_main_ui(app);
}

/* 在启动动画播放期间异步等待资源文件系统就绪。 */
static void scooter_app_ensure_storage_poll(scooter_app_ctx_t *app)
{
    if (!app || app->storage_poll_timer)
        return;

    printf("scooter_demo: start resource poll timer path=%s interval=%u\n",
           SCOOTER_STORAGE_PROBE_PATH,
           (unsigned int)SCOOTER_STORAGE_POLL_MS);
    app->storage_poll_timer = lv_timer_create(scooter_app_storage_poll_timer_cb,
                                              SCOOTER_STORAGE_POLL_MS,
                                              app);
}

/* 延后初始化主页面和控制器，确保开机动画先完整显示。 */
static void scooter_app_prepare_main_ui(scooter_app_ctx_t *app)
{
    if (!app || app->main_ui_initialized)
        return;

    printf("scooter_demo: prepare main ui begin screen_res=%ldx%ld\n",
           (long)SCOOTER_DEMO_SCREEN_WIDTH,
           (long)SCOOTER_DEMO_SCREEN_HEIGHT);

    /* 主 UI 改为统一 shell，由它内部接管页面管理和按键分发。 */
    scooter_shell_view_init(&app->shell_view,
                            &app->event_bus,
                            scooter_model_get_state(&app->model));
    scooter_main_controller_init(&app->main_controller,
                                 &app->model,
                                 scooter_shell_view_get_main_view(&app->shell_view),
                                 &app->board_service);
    scooter_shell_view_set_main_controller(&app->shell_view,
                                           &app->main_controller);
#if defined(RIVOTEK_QRCODE_SERVICE)
    scooter_app_init_qrcode(app);
#endif
    app->main_ui_initialized = true;
    printf("scooter_demo: prepare main ui done shell_screen=%p main_view=%p\n",
           (void *)app->shell_view.screen,
           (void *)scooter_shell_view_get_main_view(&app->shell_view));
}

/* 切入主页并启动业务更新，随后回收开机页。 */
static void scooter_app_show_main_ui(scooter_app_ctx_t *app)
{
    if (!app)
        return;

    if (!app->main_ui_started) {
        printf("scooter_demo: show main ui requested prepared=%d boot_finished=%d\n",
               app->main_ui_initialized ? 1 : 0,
               app->boot_anim_finished ? 1 : 0);
    }

    if (!scooter_app_storage_ready()) {
        scooter_app_ensure_storage_poll(app);
        return;
    }

    scooter_app_prepare_main_ui(app);
    if (!app->shell_view.screen) {
        printf("scooter_demo: main ui missing shell screen after prepare\n");
        return;
    }

    /* boot 结束后切入 shell，由 shell 决定当前显示的一级页面。 */
    scooter_shell_view_show(&app->shell_view);
    rvt_display_ui_refresh_now();
    printf("scooter_demo: main screen loaded screen=%p active=%p\n",
           (void *)app->shell_view.screen, (void *)lv_screen_active());

    if (app->boot_screen && app->boot_screen != app->shell_view.screen)
        lv_obj_delete_async(app->boot_screen);

    if (!app->main_ui_started) {
        scooter_main_controller_start(&app->main_controller);
        app->main_ui_started = true;
        printf("scooter_demo: main controller started\n");
    }
}

/* 创建纯开机页，先只显示 GIF，避免主页大图参与首屏绘制。 */
static void scooter_app_show_boot_screen(scooter_app_ctx_t *app)
{
    lv_obj_t *screen;
    lv_obj_t *gif;

    if (!app)
        return;

    printf("scooter_demo: create boot screen res=%ldx%ld\n",
           (long)SCOOTER_DEMO_SCREEN_WIDTH,
           (long)SCOOTER_DEMO_SCREEN_HEIGHT);

    screen = lv_obj_create(NULL);
    lv_obj_remove_style_all(screen);
    lv_obj_clear_flag(screen, LV_OBJ_FLAG_SCROLLABLE);
    lv_obj_set_size(screen, SCOOTER_DEMO_SCREEN_WIDTH, SCOOTER_DEMO_SCREEN_HEIGHT);
    lv_obj_set_style_bg_color(screen, lv_color_hex(0x000000), 0);
    lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, 0);
    lv_obj_add_event_cb(screen, scooter_app_boot_screen_event_cb, LV_EVENT_DELETE, app);

    gif = lv_gif_create(screen);
    if (!gif) {
        printf("scooter_demo: boot gif object create failed\n");
        lv_obj_delete(screen);
        scooter_app_show_main_ui(app);
        return;
    }

    lv_gif_set_src(gif, &scooter_boot_gif_asset);
    if (!lv_image_get_src(gif)) {
        printf("scooter_demo: boot gif source set failed\n");
        lv_obj_delete(screen);
        scooter_app_show_main_ui(app);
        return;
    }
    lv_obj_center(gif);
    lv_obj_add_event_cb(gif, scooter_app_boot_gif_event_cb, LV_EVENT_READY, app);

    app->boot_screen = screen;
    app->boot_gif = gif;
    scooter_app_cancel_boot_fallback_timer(app);
    app->boot_fallback_timer = lv_timer_create(scooter_app_boot_fallback_timer_cb,
                                               SCOOTER_BOOT_GIF_FALLBACK_MS,
                                               app);
    if (app->boot_fallback_timer)
        lv_timer_set_repeat_count(app->boot_fallback_timer, 1);

    lv_scr_load(screen);
    printf("scooter_demo: boot screen loaded screen=%p gif=%p active=%p fallback=%p\n",
           (void *)screen, (void *)gif, (void *)lv_screen_active(),
           (void *)app->boot_fallback_timer);
}

/* 初始化应用上下文，并启动主界面和控制器。 */
void scooter_app_init(void)
{
    scooter_state_t initial_state;

    printf("scooter_demo: init start initialized=%d\n",
           g_scooter_app.initialized ? 1 : 0);
    scooter_app_log_display_state("init start");

    if (rvt_display_init() < 0) {
        printf("scooter_demo: rvt_display_init failed\n");
        return;
    }
    if (rvt_input_init() < 0)
        printf("scooter_demo: failed to start input service\n");

    if (g_scooter_app.initialized) {
        printf("scooter_demo: init reuse main_prepared=%d\n",
               g_scooter_app.main_ui_initialized ? 1 : 0);
        if (g_scooter_app.main_ui_initialized)
            scooter_app_show_main_ui(&g_scooter_app);
        else
            scooter_app_show_boot_screen(&g_scooter_app);
        return;
    }

    rvt_event_bus_init(&g_scooter_app.event_bus);
    scooter_board_service_init(&g_scooter_app.board_service);
    scooter_board_service_fill_default_state(&initial_state);
    scooter_model_init(&g_scooter_app.model, &g_scooter_app.event_bus, &initial_state);
    rvt_time_service_init();
    rvt_weather_service_init();
#if defined(RIVOTEK_APP_SCOOTER_UI_AI_CHAT)
    rvt_ai_service_init(NULL, &g_scooter_app.event_bus);
    ai_chat_tool_bridge_init(&g_scooter_app.event_bus);
#endif

    if (rvt_time_service_start() < 0)
        printf("scooter_demo: failed to start time service\n");
    if (rvt_weather_service_start() < 0)
        printf("scooter_demo: failed to start weather service\n");
#if defined(RIVOTEK_APP_SCOOTER_UI_AI_CHAT)
    if (rvt_ai_service_start() < 0)
        printf("scooter_demo: failed to start ai service\n");
#endif
    if (rvt_audio_init() < 0)
        printf("scooter_demo: failed to start bluetooth music service\n");
#if defined(RIVOTEK_APP_SCOOTER_UI_AI_VOICE)
    if (ai_voice_init(&g_scooter_app.event_bus) < 0)
        printf("scooter_demo: failed to start ai voice adapter\n");
#endif

    scooter_app_show_boot_screen(&g_scooter_app);
    rvt_display_power_on();
    rvt_display_ui_refresh_now();
    g_scooter_app.initialized = true;
    scooter_app_log_display_state("init done");
    printf("scooter_demo: init done\n");
}

