    lv_display_get_dirty_area(disp, &dirty_area);

    struct fb_area_s fb_area;
    fb_area.x = dirty_area.x1;
    fb_area.y = dirty_area.y1 + yoffset;
    fb_area.w = lv_area_get_width(&dirty_area);
    fb_area.h = lv_area_get_height(&dirty_area);
